INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5bcea5f48085477bf0c3b20fb89dab8d','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_1","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در نوعی بیماری، به دلیل فقدان عامل انعقادی VIII (هشت)، فرایند لخته شدن خون در انسان دستخوش اختلال می‌شود. در کدام حالت زیر، تولد پسر سالم و دختر بیمار ممکن است؟\n(۱) پدر بیمار و مادر بیمار\n(۳) پدر بیمار و مادر سالم","options":["پدر بیمار و مادر بیمار","پدر سالم و مادر بیمار","پدر بیمار و مادر سالم","پدر سالم و مادر سالم"],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_1","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('c77bcb07f80aa3d607454c06f633c391','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_2","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام مورد، در خصوص آزمایشات یا نتایج کارهای گریفیت، نادرست است؟\n(۱) به بحث ها و پژوهش های چند ساله درباره ماهیت ماده ژنتیک خاتمه داد.\n(۲) دریافت که یک ویژگی ارثی می‌تواند از نوعی یاخته زنده به نوعی یاخته دیگر منتقل شود.\n(۳) در یکی از آزمایشات خود ملاحظه کرد که تعداد زیادی از باکتریهای فاقد پوشینه، پوشینه دار شدند.\n(۴) در یکی از آزمایشات انجام شده، باکتری های پوشینه دار زنده را در محلی غیر از خون موش های مرده مشاهده کرد.","options":["به بحث ها و پژوهش های چند ساله درباره ماهیت ماده ژنتیک خاتمه داد.","دریافت که یک ویژگی ارثی می‌تواند از نوعی یاخته زنده به نوعی یاخته دیگر منتقل شود.","در یکی از آزمایشات خود ملاحظه کرد که تعداد زیادی از باکتریهای فاقد پوشینه، پوشینه دار شدند.","در یکی از آزمایشات انجام شده، باکتری های پوشینه دار زنده را در محلی غیر از خون موش های مرده مشاهده کرد."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_2","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('785e8bbe428d459d6e9ff4e6526585c5','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_4","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"یاخته های سازنده دیواره حبابک تنفسی انسان که به صورت پراکنده در بین نوع دیگری از یاخته های این دیواره قرار گرفته اند، چه مشخصه ای دارند؟\n(۱) جزیی از مخاط مژک دار به شمار می‌آیند.\n(۲) به شکل سنگفرشی و تک لایه ای هستند.\n(۳) یاخته های مرده و بقایای آنها را پاکسازی می‌کنند.\n(۴) بر روی شبکه ای از رشته های پروتئینی قرار گرفته اند.","options":["جزیی از مخاط مژک دار به شمار می‌آیند.","به شکل سنگفرشی و تک لایه ای هستند.","یاخته های مرده و بقایای آنها را پاکسازی می‌کنند.","بر روی شبکه ای از رشته های پروتئینی قرار گرفته اند."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_4","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e3ad98af794322e183ddca28ded9561b','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_5","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"به طور معمول، در ارتباط با رنگ درخشان طاووس نر و لکه های چشم مانندی که بر روی پرهای دم این جانور دیده می‌شود، کدام مورد درست است؟\n(۱) احتمال بقای این جانور را افزایش می‌دهد.\n(۲) از دوران بچگی این جانور ایجاد شده است.\n(۳) ضامن سلامت جانور ماده و زاده هایش است.\n(۴) پس از پدیدار شدن تا انتهای دوران حیات جانور باقی می‌ماند.","options":["احتمال بقای این جانور را افزایش می‌دهد.","از دوران بچگی این جانور ایجاد شده است.","ضامن سلامت جانور ماده و زاده هایش است.","پس از پدیدار شدن تا انتهای دوران حیات جانور باقی می‌ماند."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_5","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('91df3389f6ef2d15131eb109a4a007c9','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_6","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص ساختار چشم سالم یک فرد، چند مورد زیر صحیح است؟\nالف - نقطه کور توسط صلبیه پوشیده شده است.\nب - لکه زرد، به دلیل ضخیم شدن شبکیه، شکل برجسته ای پیدا می‌کند.\nج - بخشی از آسه (آکسون) های عصب بینایی پس از خروج از کره چشم به سمت نیمکره مخ مقابل می‌روند.\nد - جریان خون از طریق یک سرخرگ وارد کره چشم شده و در محل نقطه کور انشعاب می‌یابد.","options":["۱","۲","۳","۴"],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_6","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('c76c3382fefca5f81c4c12c44be5847e','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_7","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص عوامل برهم زننده تعادل جمعیت، کدام مورد زیر را می‌توان بیان نمود؟\n(۱) یکی از آنها باعث می‌شود تا احتمال بقا و تولیدمثل برای همه افراد جمعیت یکسان باقی بماند.\n(۲) همه آنها به هر دو صورت تصادفی و غیرتصادفی، فراوانی نسبی دگره‌ها را تغییر می‌دهند.\n(۳) یکی از آنها با توجه به تفاوت‌های فردی، در پایداری گونه مؤثر است.\n(۴) همه آنها، در جمعیت‌های مختلف نتایج یکسانی به بار می‌آورند.","options":["یکی از آنها باعث می‌شود تا احتمال بقا و تولیدمثل برای همه افراد جمعیت یکسان باقی بماند.","همه آنها به هر دو صورت تصادفی و غیرتصادفی، فراوانی نسبی دگره‌ها را تغییر می‌دهند.","یکی از آنها با توجه به تفاوت‌های فردی، در پایداری گونه مؤثر است.","همه آنها، در جمعیت‌های مختلف نتایج یکسانی به بار می‌آورند."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_7","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('42bf61188dc836b2447d67413c63b290','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_8","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در ارتباط با یاخته‌های مراحل تولید زامه (اسپرم) انسان، کدام مورد نادرست است؟\n(۱) هر یاخته‌ای که می‌تواند دنای خود را دو برابر کند، قادر است مجموعه‌ای از ریزلوله‌های پروتئینی را تشکیل دهد.\n(۲) هر یاخته‌ای که حلقه انقباضی تشکیل می‌دهد، در آغاز تقسیم، فامتن (کروموزوم)های مضاعف داشته است.\n(۳) هر یاخته‌ای که حالت کاملاً کشیده و هسته‌ای فشرده پیدا می‌کند، فامتن (کروموزوم)های ناهمتا دارد.\n(۴) هر یاخته‌ای که دارای میانک (سانتریول)های مضاعف شده است، فامتن‌های همتا دارد.","options":["هر یاخته‌ای که می‌تواند دنای خود را دو برابر کند، قادر است مجموعه‌ای از ریزلوله‌های پروتئینی را تشکیل دهد.","هر یاخته‌ای که حلقه انقباضی تشکیل می‌دهد، در آغاز تقسیم، فامتن (کروموزوم)های مضاعف داشته است.","هر یاخته‌ای که حالت کاملاً کشیده و هسته‌ای فشرده پیدا می‌کند، فامتن (کروموزوم)های ناهمتا دارد.","هر یاخته‌ای که دارای میانک (سانتریول)های مضاعف شده است، فامتن‌های همتا دارد."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_8","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('0a9598a7186bec7f2c8f448854c01973','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_9","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"با توجه به نمودار توزیع فراوانی مربوط به رنگ ذرت که در کتاب درسی آمده است و با فرض اینکه گروهی با بیشترین فراوانی گروه A و گروهی با کمترین فراوانی گروه B نامیده شود، کدام مورد زیر درست است؟\n(۱) فقط بعضی از افرادی که در گروه مجاور با گروه A قرار دارند، در سه جایگاه ژنی خالص اند.\n(۲) فقط بعضی از افرادی که در گروه مجاور با گروه B قرار دارند، در دو جایگاه ژنی خالص اند.\n(۳) همه افرادی که در گروه B قرار دارند، در یک جایگاه ژنی ناخالص اند.\n(۴) همه افرادی که در گروه A قرار دارند، در دو جایگاه ژنی خالص اند.","options":["فقط بعضی از افرادی که در گروه مجاور با گروه A قرار دارند، در سه جایگاه ژنی خالص اند.","فقط بعضی از افرادی که در گروه مجاور با گروه B قرار دارند، در دو جایگاه ژنی خالص اند.","همه افرادی که در گروه B قرار دارند، در یک جایگاه ژنی ناخالص اند.","همه افرادی که در گروه A قرار دارند، در دو جایگاه ژنی خالص اند."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_9","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('96d6aab2a8b12ecdcfb6c435f9744dc0','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_10","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"با توجه به اطلاعات کتاب درسی، در ارتباط با غشای یاخته حرکتی شرکت کننده در انعکاس عقب کشیدن دست انسان، کدام مورد نادرست است؟\n(۱) فقط بعضی از پروتئین‌هایی که یون‌های پتاسیم را از غشای یاخته عبور می‌دهند، نیاز به صرف انرژی زیستی دارند.\n(۲) همه پروتئین‌هایی که باعث جابجا شدن یون‌های سدیم می‌شوند، از عبور یون‌های پتاسیم ممانعت به عمل می‌آورند.\n(۳) فقط بعضی از کانال‌های پروتئینی که به یون‌های سدیم اجازه عبور می‌دهند، به هنگام پتانسیل عمل باز می‌شوند.\n(۴) همه پروتئین‌هایی که به یون‌های پتاسیم اجازه عبور می‌دهند، در سراسر عرض غشا قرار دارند.","options":["فقط بعضی از پروتئین‌هایی که یون‌های پتاسیم را از غشای یاخته عبور می‌دهند، نیاز به صرف انرژی زیستی دارند.","همه پروتئین‌هایی که باعث جابجا شدن یون‌های سدیم می‌شوند، از عبور یون‌های پتاسیم ممانعت به عمل می‌آورند.","فقط بعضی از کانال‌های پروتئینی که به یون‌های سدیم اجازه عبور می‌دهند، به هنگام پتانسیل عمل باز می‌شوند.","همه پروتئین‌هایی که به یون‌های پتاسیم اجازه عبور می‌دهند، در سراسر عرض غشا قرار دارند."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_10","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('7633d2d57cfb53a4aaee571d6d9ad063','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_11","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص هر پرده موجود در گوش انسان که استخوان کوچکی بر روی آن تکیه دارد، کدام مورد یا موارد زیر را می‌توان بیان نمود؟\nالف - در مجاورت مجرای شنوایی قرار دارد.\nب - توسط استخوان گیجگاهی محافظت می‌شود.\nج - امواج صوتی را به محفظه‌ای استخوانی و پر از هوا منتقل می‌کند.\nد - نقش مؤثری در تحریک همه یاخته‌های مژکدار گوش درونی دارد.\n(۱) «الف»، «ج» و «د»\n(۲) «ب»، «ج» و «د»\n(۳) «الف»\n(۴) «ب»","options":["«الف»، «ج» و «د»","«ب»، «ج» و «د»","«الف»","«ب»"],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_11","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5fe00f3770859d3f1dbdfd70268ef527','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_12","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص مهندسی ژنتیک و فناوری مهندسی پروتئین، کدام مورد نادرست است؟\n(۱) هر پروتئینی که جهت مصارف درمانی ساخته می‌شود، در بدن فرد پاسخ‌های ایمنی شدید ایجاد می‌کند.\n(۲) در پی ایجاد تغییرات گسترده در توالی آمینواسیدها، شکل و عملکرد پروتئین دستخوش تغییر می‌شود.\n(۳) می‌توان با ایجاد تغییرات دلخواه در توالی آمینواسیدها، دارویی با پایداری طولانی مدت ساخت.\n(۴) می‌توان با تغییر در رمز یک یا چند آمینواسید، تغییر جزیی در ساختار پروتئین ایجاد کرد.","options":["هر پروتئینی که جهت مصارف درمانی ساخته می‌شود، در بدن فرد پاسخ‌های ایمنی شدید ایجاد می‌کند.","در پی ایجاد تغییرات گسترده در توالی آمینواسیدها، شکل و عملکرد پروتئین دستخوش تغییر می‌شود.","می‌توان با ایجاد تغییرات دلخواه در توالی آمینواسیدها، دارویی با پایداری طولانی مدت ساخت.","می‌توان با تغییر در رمز یک یا چند آمینواسید، تغییر جزیی در ساختار پروتئین ایجاد کرد."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_12","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a8c65b3946b00953430f85c71264cac5','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_15","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در ارتباط با انتقال مواد مورد نیاز درخت بلوط، کدام مورد نادرست است؟","options":["آب به صورت بخار وارد فضای بین یاخته های میانبرگ اسفنجی میشود.","یونها به هنگام ورود به عناصر آوندی از مسیر سیمپلاستی ریشه خارج شده اند.","درون پوست (آندودرم) ریشه از برگشت یونها به سمت یاخته های تار کشنده ممانعت به عمل می آورد.","در پی کشته شدن یاخته های آوند آبکش، حرکت شیره پرورده در این یاخته ها همچنان ادامه می یابد."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_15","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('8a5e984b7996bd230e79c61e22d5ac79','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_16","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"نوعی تنظیم کننده رشد گیاهی باعث تحریک رشد و نمو نهنج گلهای درخت سیب میشود. کدام دو نقش زیر به این تنظیم کننده اختصاص دارد؟","options":["ریزش برگ چنار و رشد طولی ساقه گیاه نخود","طویل کردن گیاه کلم و افزایش رونویسی ژن آمیلاز در دانه گندم","بزرگ نمودن غنچه های گل شمعدانی و رساندن هلوی نارس در انبار","تغییر چیرگی راسی در گیاه ذرت و مقاومت گیاه پسته در برابر کم آبی"],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_16","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('1021f0c42fe45b21f126f4297c3d8b28','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_17","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص یک مرد ۲۵ ساله و سالم، چند مورد زیر صحیح است؟\nالف - با تزریق تستوسترون اضافی به بدن پس از مدتی ترشح LH کاهش می یابد.\nب - با قطع مجرای زامه بر مسیر عبور زامه (اسپرم)ها به برخاگ (اپیدیدیم) مسدود میشود.\nج - در صورت حضور فرد در استخر آب بسیار گرم به مدت طولانی، فرایند تبدیل زام یاختک (اسپرماتید) به زامه (اسپرم) کاهش می یابد.\nد - هورمون محرک جنسی مستقیماً بر یاخته های بافتی تأثیر میگذارد که این غده را به بخشهای هرمی شکل تقسیم نموده است.","options":["۱","۲","۳","۴"],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_17","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('75ab7efbf2d02a47ad3605bc8aaf11b9','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_18","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی در ارتباط با هر مولکول شش کربنی که در طی دو فرایند زیستی مهم یعنی واکنشهای تثبیت کربن و چرخه کربس در اوگلنا ساخته میشود، کدام مورد به طور حتم درست است؟","options":["ابتدا به ترکیب فسفات دار تجزیه میشود.","در داخل نوعی اندامک دو غشایی ایجاد میشود.","ترکیبی سه کربنی را تولید و از چرخه خارج میکند.","یکی از پیش ماده های آن محصول اکسایش قند است."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_18","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
