INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('06eeddadff3c032c9449c859988c3514','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_24","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی کدام مورد برای تکمیل عبارت زیر نامناسب است؟\nپیک های شیمیایی که ساختار پروتئینی دارند و .................","options":["در یاخته های مجرا تغییر ایجاد میکنند به طور حتم توسط نوعی غده برون ریز ساخته شده اند","از طریق بازخورد منفی تنظیم میشوند در مقادیر بسیار کم ترشح شده اند","به خون وارد میشوند ممکن است از غده یا یاخته های درون ریز ترشح شده باشند","پس از ترشح بر روی چندین نوع یاخته تأثیر میگذارند به طور حتم مدتی در درون ریز کیسه (وزیکول) هایی قرار داشته اند"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_24","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('b6b136c97c323d8873ec30c0f1ea0b82','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_25","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"اگر در یک خانم جوان که معمولاً چرخه تخمدانی ۲۸ روزه دارد، میزان استروژن خون در حدود روز چهاردهم دوره، در سطح پایینی باقی بماند، در آن زمان کدام اتفاق روی میدهد؟","options":["میزان ترشح FSH بدون تغییر می ماند.","هورمون دیگر تخمدان افزایش چشم گیری می یابد.","ضخامت دیواره داخلی رحم در حد پایینی باقی میماند.","از فعالیت ترشحی باقیمانده انبانک بالغ موجود در تخمدان کاسته میشود."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_25","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ae337c9ae3720919eebc10dd33c9ca39','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_26","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در ارتباط با تنظیمات شیمیایی بدن یک مرد ۲۰ ساله کدام مورد را می توان بیان نمود؟","options":["هورمون جنسی مردانه بر افزایش ماده زمینهای استخوان و تراکم آن تأثیر گذار است.","با ترشح طولانی مدت کورتیزول، تولید رشته های اکتین و میوزین در عضلات اسکلتی افزایش می یابد.","در پی آسیب به یاخته های ترشح کننده انسولین غلظت گلیسرول در خون فرد کاهش محسوسی می یابد.","در انتهای روزه داری و همزمان شدن آن با فعالیتهای ورزشی شدید ابتدا ترشح گلوکاگون و سپس ترشح انسولین کاهش می یابد."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_26","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e733d13dac5ab4f33ffb5a8227eea9e5','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_27","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام مورد در ارتباط با «گیاه گوجه‌فرنگی»، نادرست است؟\n(۱) می‌تواند در همۀ فصول سال، مریستم رویشی جوانه را به مریستم زایشی تبدیل نماید.\n(۲) جوانه جانبی ساقۀ آن از نظر اندازه از جوانۀ انتهایی ساقه، تاحدودی کوچک‌تر است.\n(۳) دستجات آوندی در ساقۀ آن، بر روی یک دایره قرار گرفته‌اند.\n(۴) می‌تواند میوه‌ای کاذب با دانه‌های فراوان تولید کند.","options":["می‌تواند در همۀ فصول سال، مریستم رویشی جوانه را به مریستم زایشی تبدیل نماید.","جوانه جانبی ساقۀ آن از نظر اندازه از جوانۀ انتهایی ساقه، تاحدودی کوچک‌تر است.","دستجات آوندی در ساقۀ آن، بر روی یک دایره قرار گرفته‌اند.","می‌تواند میوه‌ای کاذب با دانه‌های فراوان تولید کند."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_27","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
