INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('30a1b4f6b9b99ee2da3631a2a8251013','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_31","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی، کدام عبارت در ارتباط با «اشرشیاکلای»، نادرست است؟\n(۱) در فرایندهای تجزیه کامل گلوکز و لاکتوز، تعدادی از آنزیم‌ها مشترک‌اند.\n(۲) در نوعی تنظیم بیان ژن، پس از ورود مالتوز به محیط کشت باکتری، قند به فعال کننده متصل می‌شود.\n(۳) در نوعی تنظیم بیان ژن، با دور شدن دو بخش از ساختار مهارکننده از یکدیگر، رنابسپار از فعال می‌شود.\n(۴) در صورت وجود لاکتوز در محیط کشت باکتری، به‌طور حتم ژن‌های مربوط به تجزیه این قند به مقدار زیاد رونویسی می‌شوند.","options":["در فرایندهای تجزیه کامل گلوکز و لاکتوز، تعدادی از آنزیم‌ها مشترک‌اند.","در نوعی تنظیم بیان ژن، پس از ورود مالتوز به محیط کشت باکتری، قند به فعال کننده متصل می‌شود.","در نوعی تنظیم بیان ژن، با دور شدن دو بخش از ساختار مهارکننده از یکدیگر، رنابسپار از فعال می‌شود.","در صورت وجود لاکتوز در محیط کشت باکتری، به‌طور حتم ژن‌های مربوط به تجزیه این قند به مقدار زیاد رونویسی می‌شوند."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_31","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('423316954edc9472fe738f85d6df8b38','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_32","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"چند مورد برای تکمیل عبارت زیر مناسب است؟\nبخش عقبی معده کبوتر .................... حجیم‌ترین بخش از لوله گوارش آن ....................\nالف - همانند – در ناحیه شکم جانور قرار گرفته است.\nب - برخلاف – اغلب آنزیم‌های گوارشی را ترشح می‌کند.\nج - برخلاف – مستقیماً ترشحات کبد را دریافت می‌کند.\nد - همانند – به اندامی متصل است که می‌تواند غذا را تا حدودی خرد و تجزیه کند.","options":["۱","۲","۳","۴"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_32","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('3148013411c8b4cd5040f574e53a0b72','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_33","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص فرایندهای مختلف ایمنی در بدن انسان، کدام مورد درست است؟\n(۱) لنفوسیت دفاع غیر اختصاصی، ابتدا منافذی در غشای یاخته هدف ایجاد و سپس پرفورین ترشح می‌کند.\n(۲) فقط در پی بعضی از روش‌های غیر فعال شدن پادگن توسط پادتن است که بیگانه خواری افزایش می‌یابد.\n(۳) هر مولکولی که پادگن را شناسایی می‌کند، فقط می‌تواند به یک نوع یاخته متصل شود.\n(۴) یاخته‌ای که مرگ برنامه‌ریزی شده را آغاز کرده، ظاهری دانه‌دانه پیدا خواهد کرد.","options":["لنفوسیت دفاع غیر اختصاصی، ابتدا منافذی در غشای یاخته هدف ایجاد و سپس پرفورین ترشح می‌کند.","فقط در پی بعضی از روش‌های غیر فعال شدن پادگن توسط پادتن است که بیگانه خواری افزایش می‌یابد.","هر مولکولی که پادگن را شناسایی می‌کند، فقط می‌تواند به یک نوع یاخته متصل شود.","یاخته‌ای که مرگ برنامه‌ریزی شده را آغاز کرده، ظاهری دانه‌دانه پیدا خواهد کرد."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_33","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('51f17d690a016d45dfa79d8c867250a7','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_34","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"بخشی که مام یاخته (اووسیت) ثانویه را احاطه کرده و رابط میان مام یاخته و باقیمانده یاخته‌های انبانکی (فولیکولی)است، کدام مشخصه زیر را ندارد؟\n(۱) می‌تواند اولین جسم قطبی را احاطه نماید.\n(۲) قبل از تشکیل دومین جسم قطبی، کاملاً تجزیه می‌شود.\n(۳) در شرایطی تحت تأثیر مولکولی با عمل اختصاصی قرار می‌گیرد.\n(۴) می‌تواند تحت تأثیر محتویات ریز کیسه (وزیکولهای) مام یاخته قرار گیرد.","options":["می‌تواند اولین جسم قطبی را احاطه نماید.","قبل از تشکیل دومین جسم قطبی، کاملاً تجزیه می‌شود.","در شرایطی تحت تأثیر مولکولی با عمل اختصاصی قرار می‌گیرد.","می‌تواند تحت تأثیر محتویات ریز کیسه (وزیکولهای) مام یاخته قرار گیرد."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_34","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('c55ede78590176a8ce639214962e7a2d','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_35","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در برش عرضی ریشه نوعی گیاه، آوندهای چوبی ظاهری ستاره مانند را ایجاد می‌کنند و آوندهای آبکش فاصله بین بازوهای این بخش ستاره‌ای را پر کرده‌اند. به طور معمول، کدام مورد درباره برگ این گیاه صادق است؟\n(۱) در ساختار دمبرگ آن، سه سامانه بافتی وجود دارد.\n(۲) لایه محافظ در سمت بیرونی لایه جدا کننده دمبرگ آن ایجاد می‌شود.\n(۳) یاخته‌های نرده‌ای برگ نسبت به یاخته‌های اسفنجی، به روپوست زیرین نزدیک‌ترند.\n(۴) تعداد سبز دیسه (کلروپلاست)های هر یاخته اسفنجی پهنک بیش از هر یاخته نرده‌ای آن است.","options":["در ساختار دمبرگ آن، سه سامانه بافتی وجود دارد.","لایه محافظ در سمت بیرونی لایه جدا کننده دمبرگ آن ایجاد می‌شود.","یاخته‌های نرده‌ای برگ نسبت به یاخته‌های اسفنجی، به روپوست زیرین نزدیک‌ترند.","تعداد سبز دیسه (کلروپلاست)های هر یاخته اسفنجی پهنک بیش از هر یاخته نرده‌ای آن است."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_35","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('2bdfd0fdc686df8c5c6c1e466c9b4576','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_37","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در ارتباط با تارهای عضله سه سر بازوی یک پسر نوجوان که شنا را به طور حرفه‌ای دنبال می‌کند، به طور معمول، کدام مورد نادرست است؟\n(۱) تراکم راکیزه (میتوکندری)های تارهای عضلانی اش افزایش خواهد یافت.\n(۲) تحت تأثیر نوعی پیک شیمیایی، بر ضخامت تارهای عضلانی اش افزوده خواهد شد.\n(۳) در شرایطی خون بیشتری در رگهای درون تار عضلانی اش جریان پیدا خواهد کرد.\n(۴) در غشای تارهای عضلانی اش، نوعی پروتئین کانالی وجود دارد که تحت تأثیر نوعی ماده شیمیایی فعال می‌شود.","options":["تراکم راکیزه (میتوکندری)های تارهای عضلانی اش افزایش خواهد یافت.","تحت تأثیر نوعی پیک شیمیایی، بر ضخامت تارهای عضلانی اش افزوده خواهد شد.","در شرایطی خون بیشتری در رگهای درون تار عضلانی اش جریان پیدا خواهد کرد.","در غشای تارهای عضلانی اش، نوعی پروتئین کانالی وجود دارد که تحت تأثیر نوعی ماده شیمیایی فعال می‌شود."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_37","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a4d4f26c69d666ad9aaac3ed95a0c543','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_38","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"چند مورد، در خصوص فردی با رژیم غذایی معمولی صحیح است؟\nالف - به دنبال ایجاد پارگی‌های جزیی در رگهای بسیار کوچک بدن، ابتدا ترشح پروترومبیناز افزایش چشمگیری می‌یابد.\nب - در پی ابتلای فرد به بیماری انسدادی مجرای صفرا، احتمال وارد شدن آسیب به ابتدای روده باریک وجود دارد.\nج - در پی ابتلای فرد به بیماری سلیاک، احتمال کاهش تراکم توده استخوانی وجود دارد.\nد - در محیط‌های بی وزنی، توده استخوانی فرد بدون تغییر باقی می‌ماند.\n(1) ۲\n(2) ۱\n(3) ۴\n(4) ۳","options":["۲","۱","۴","۳"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_38","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('240aba6b2105d160c0aa7c38cba02982','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_40","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در نوعی جانور ماده، به دنبال انقباض بطن، خون جهت تبادلات گازی با هوا به سمت ششها و پوست هدایت میشود. به طور معمول، کدام مورد زیر درباره این جانور صادق نیست؟\n(۱) با بستن سوراخ های بینی هوا را از حفره دهانی به سمت ششها روانه میکند.\n(۲) میتواند آب را از طریق یاخته های سطحی نوعی کیسه ماهیچه ای به خون وارد کند.\n(۳) سامانه دفعی آن سراسر لوله ای شکل است و مستقیماً از طریق منفذی به بیرون باز میشود.\n(۴) ساختاری را تولید میکند که در محافظت جنین در برابر عوامل نامساعد محیطی نقش مؤثری دارد.","options":["با بستن سوراخ های بینی هوا را از حفره دهانی به سمت ششها روانه میکند.","میتواند آب را از طریق یاخته های سطحی نوعی کیسه ماهیچه ای به خون وارد کند.","سامانه دفعی آن سراسر لوله ای شکل است و مستقیماً از طریق منفذی به بیرون باز میشود.","ساختاری را تولید میکند که در محافظت جنین در برابر عوامل نامساعد محیطی نقش مؤثری دارد."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_40","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('f26962d2061fcca86fc8bdce2b6303e4','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_41","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی، با توجه به اجزای زنجیره انتقال الکترون در گیاه رز، ناقل الکترونی موردنظر است که مستقیماً باعث میشود تا ساختاری نوکلئوتیدی، دستخوش کاهش شود (نه اکسایش). کدام مورد زیر را میتوان درباره این ناقل بیان نمود؟\n(۱) در سطح خارجی نوعی اندامک واقع شده است.\n(۲) در پی تجزیه نوعی مولکول غیر آلی فعالیت میکند.\n(۳) پروتونها را بر اساس شیب غلظت خود عبور میدهد.\n(۴) در مجاورت آنزیم ATP ساز (به روش اکسایشی) قرار گرفته است.","options":["در سطح خارجی نوعی اندامک واقع شده است.","در پی تجزیه نوعی مولکول غیر آلی فعالیت میکند.","پروتونها را بر اساس شیب غلظت خود عبور میدهد.","در مجاورت آنزیم ATP ساز (به روش اکسایشی) قرار گرفته است."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_41","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('4ab1309c35732d5197ab09a279efd594','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_42","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص فرایند ترجمه، کدام مورد را نمیتوان بیان داشت؟\n(۱) پس از جدا شدن رشته پلی پپتید از آخرین رنای ناقل، عامل آزاد کننده رها میشود.\n(۲) قطع پیوند میان tRNA و بسپار، میتواند در خارج از جایگاه P رناتن (ریبوزوم) رخ دهد.\n(۳) همزمان با اتصال رنای ناقل به رمزه آغاز، جایگاه P رناتن (ریبوزوم) به طور کامل شکل می گیرد.\n(۴) در هر مرحله آن، زمان یا زمانهایی وجود دارد که فقط یک جایگاه رناتن (ریبوزوم) توسط tRNA پر شده است.","options":["پس از جدا شدن رشته پلی پپتید از آخرین رنای ناقل، عامل آزاد کننده رها میشود.","قطع پیوند میان tRNA و بسپار، میتواند در خارج از جایگاه P رناتن (ریبوزوم) رخ دهد.","همزمان با اتصال رنای ناقل به رمزه آغاز، جایگاه P رناتن (ریبوزوم) به طور کامل شکل می گیرد.","در هر مرحله آن، زمان یا زمانهایی وجود دارد که فقط یک جایگاه رناتن (ریبوزوم) توسط tRNA پر شده است."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_42","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('28be8d925450a8488564c0e8c8361c6d','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_43","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"با توجه به بخشهای موردنظر در شکل زیر، کدام مورد درست است؟ (لازم به ذکر است بخش D در بالای بصل النخاع و جلوی مخچه قرار دارد).\n(۱) بخش A همانند بخش C، در پاسخهای سریع و غیرارادی ماهیچهها نقش اصلی را دارد.\n(۲) بخش D برخلاف بخش C، به غده ترشح کننده ملاتونین چسبیده است.\n(۳) بخش C برخلاف بخش A، اعصابی را به سمت دستها میفرستد.\n(۴) بخش B همانند بخش D، بر افزایش و کاهش فعالیت قلب تأثیر می گذارد.","options":["بخش A همانند بخش C، در پاسخهای سریع و غیرارادی ماهیچهها نقش اصلی را دارد.","بخش D برخلاف بخش C، به غده ترشح کننده ملاتونین چسبیده است.","بخش C برخلاف بخش A، اعصابی را به سمت دستها میفرستد.","بخش B همانند بخش D، بر افزایش و کاهش فعالیت قلب تأثیر می گذارد."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/tajrobi_nobat1_43.jpg"],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_43","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('dd59db6091b4158f9c2180ff0a9cf10b','persian-konkur-1404-first-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_44","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی، کدام مورد درباره سرنوشت پلی پپتیدهای ساخته شده در سیتوپلاسم یاخته لوزالمعده انسان صادق است؟\n(۱) همۀ پلی پپتیدهایی که توسط اندامکی بسته بندی شده اند، به خارج از یاخته منتقل خواهند شد.\n(۲) بعضی از پلی پپتیدهایی که در خارج از اندامک غشادار ساخته شده اند، به اندامکهای دنا دار وارد میشوند.\n(۳) همۀ پلی پپتیدهایی که توسط هر اندامک غشادار ساخته شده اند، توسط اندامکی دیگر دستخوش تغییر میشوند.\n(۴) اغلب پلی پپتیدهایی که در داخل اندامک غشاداری ساخته شده اند، به درون ماده زمینهای سیتوپلاسم منتقل میشوند.","options":["همۀ پلی پپتیدهایی که توسط اندامکی بسته بندی شده اند، به خارج از یاخته منتقل خواهند شد.","بعضی از پلی پپتیدهایی که در خارج از اندامک غشادار ساخته شده اند، به اندامکهای دنا دار وارد میشوند.","همۀ پلی پپتیدهایی که توسط هر اندامک غشادار ساخته شده اند، توسط اندامکی دیگر دستخوش تغییر میشوند.","اغلب پلی پپتیدهایی که در داخل اندامک غشاداری ساخته شده اند، به درون ماده زمینهای سیتوپلاسم منتقل میشوند."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_44","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
