INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ffcd8cbaa7afd7eaadde9ec3075d3936','persian-konkur-1404-first-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_76","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"کدام مورد درست است؟\n(۱) یکی از راههای تعیین آرایش الکترونی، برانگیخته کردن اتم و بررسی پرتوهای گسیل شده از آن است.\n(۲) در اتم هیدروژن، تفاوت انرژی الکترونها در دو لایه متوالی با نزدیک شدن لایه ها به هسته، کاهش می یابد.\n(۳) اگر به اتمهای گازی شکل یک عنصر، انرژی داده شود، الکترون میتواند با جذب هر مقدار انرژی به لایه های بالاتر انتقال یابد.\n(۴) در اتم هیدروژن، انرژی آزاد شده انتقال الکترون از لایه چهارم به لایه دوم، بیشتر از انرژی آزاد شده انتقال الکترون از لایه پنجم به لایه دوم است.","options":["یکی از راههای تعیین آرایش الکترونی، برانگیخته کردن اتم و بررسی پرتوهای گسیل شده از آن است.","در اتم هیدروژن، تفاوت انرژی الکترونها در دو لایه متوالی با نزدیک شدن لایه ها به هسته، کاهش می یابد.","اگر به اتمهای گازی شکل یک عنصر، انرژی داده شود، الکترون میتواند با جذب هر مقدار انرژی به لایه های بالاتر انتقال یابد.","در اتم هیدروژن، انرژی آزاد شده انتقال الکترون از لایه چهارم به لایه دوم، بیشتر از انرژی آزاد شده انتقال الکترون از لایه پنجم به لایه دوم است."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_76","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a5b39e1223b473c43c188b37c8f900ac','persian-konkur-1404-first-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_77","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"اگر مجموع شمار الکترونهای بیرونی ترین زیرلایه الکترونی در اتم دو عنصر در دوره دوم جدول تناوبی عنصرها برابر ۹ باشد، کدام مورد نادرست است؟\n(۱) تفاوت شمار الکترونهای ظرفیت اتم دو عنصر میتواند برابر یک باشد.\n(۲) آخرین زیر لایه اتم یکی از عنصرها میتواند پر و دیگری نیمه پر باشد.\n(۳) عدد اتمی یک عنصر میتواند ۷ و ۵ عدد اتمی عنصر دیگر باشد.\n(۴) تفاوت عدد اتمی دو عنصر، عددی زوج است.","options":["تفاوت شمار الکترونهای ظرفیت اتم دو عنصر میتواند برابر یک باشد.","آخرین زیر لایه اتم یکی از عنصرها میتواند پر و دیگری نیمه پر باشد.","عدد اتمی یک عنصر میتواند ۷ و ۵ عدد اتمی عنصر دیگر باشد.","تفاوت عدد اتمی دو عنصر، عددی زوج است."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_77","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('8ee1e4e9988042d8af78a7a2aa8e49d7','persian-konkur-1404-first-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_80","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"کدام مورد درست است؟\n(۱) واکنش دهنده های فرایند تشکیل اوزون در استراتوسفر و تروپوسفر، مشابه یکدیگرند.\n(۲) دگر شکلهای هر عنصر، خواص شیمیایی یکسان، اما خواص فیزیکی متفاوت دارند.\n(۳) واکنش تشکیل اوزون از اکسیژن در تروپوسفر، برگشت پذیر و تعادلی است.\n(۴) سطح انرژی مولکول اوزون، بالاتر از سطح انرژی مولکول اکسیژن است.","options":["واکنش دهنده های فرایند تشکیل اوزون در استراتوسفر و تروپوسفر، مشابه یکدیگرند.","دگر شکلهای هر عنصر، خواص شیمیایی یکسان، اما خواص فیزیکی متفاوت دارند.","واکنش تشکیل اوزون از اکسیژن در تروپوسفر، برگشت پذیر و تعادلی است.","سطح انرژی مولکول اوزون، بالاتر از سطح انرژی مولکول اکسیژن است."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_80","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
