INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('8ace22406008ce26cf97e4eaea33d984','persian-konkur-1404-first-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_99","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"شکلهای زیر، دو ظرف مشابه دارای حجم معینی از محلولها با مشخصات بیان شده و در دمای اتاق را نشان میدهد. با توجه به آن، کدام مورد، نادرست است؟","options":["تفاوت pH دو محلول برابر ۱۲ و رسانایی دو محلول، به تقریب برابر است.","اگر دو محلول به یکدیگر اضافه شوند، pH برابر ۷ خواهد شد و محلول تشکیل شده، الکترولیت است.","اگر به محلول نیتریک اسید، ۸۰۰ میلی لیتر آب مقطر اضافه شود، تفاوت غلظت مولی دو محلول برابر ۰.۰۴ خواهد شد.","مجموع شمار یونها در دو محلول برابر ۰.۰۸ مول است و کاتیون باز و آنیون اسید در هر یک از محلولها آبپوشیده شدهاند."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/tajrobi_nobat1_99.jpg"],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_99","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('48f0bbbf0c58848c1693c30c4c6a3514','persian-konkur-1404-first-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_107","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"در کدام موارد، ساختار بیان شده درباره جامد مربوطه درست است؟\nالف ـ جامد فلزی: آرایش منظم کاتیون‌ها در سه بعد\nب ـ جامد مولکولی: آرایش منظم اتم‌ها در سه بعد\nج ـ جامد کووالانسی: چینش دو یا سه بعدی از اتم‌ها\nد ـ جامد یونی: چینش دو یا سه بعدی از یون‌های مثبت و منفی","options":["«ب» و «د»","«ب» و «ج»","«الف» و «د»","«الف» و «ج»"],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_107","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('644b89fc473f610e98b3f972e2f758b8','persian-konkur-1404-first-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_108","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"کدام مورد نادرست است؟\n(۱) گاز متان، سازنده اصلی گاز طبیعی است که در میدان‌های نفتی برای افزایش ایمنی، بخش قابل توجهی از آن را می‌سوزانند.\n(۲) در شرایط مناسب و طی واکنش‌های کاهش اتن و پارازایلن، مونومرهای سازنده PET تهیه می‌شود.\n(۳) در شرایط مناسب، با استفاده از کاتالیزگر و گاز اکسیژن، می‌توان گاز متان را به متانول تبدیل کرد.\n(۴) تبدیل متان به متانول دشوار است و به دانش و فناوری پیشرفته نیاز دارد.","options":["گاز متان، سازنده اصلی گاز طبیعی است که در میدان‌های نفتی برای افزایش ایمنی، بخش قابل توجهی از آن را می‌سوزانند.","در شرایط مناسب و طی واکنش‌های کاهش اتن و پارازایلن، مونومرهای سازنده PET تهیه می‌شود.","در شرایط مناسب، با استفاده از کاتالیزگر و گاز اکسیژن، می‌توان گاز متان را به متانول تبدیل کرد.","تبدیل متان به متانول دشوار است و به دانش و فناوری پیشرفته نیاز دارد."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_108","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
