INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('200d064826f9d260aaff70e88093b36d','persian-konkur-1404-first-geology-1','geology','زمین‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_143","subjectId":"geology","chapter":"زمین‌شناسی — کنکور ۱۴۰۴","prompt":"طبق نظریه زمین مرکزی، به جای عددهای ۱ تا ۴ در روی شکل، به ترتیب کدام جرم‌های فضایی قرار می‌گیرند؟\n(۱) ماه، خورشید، عطارد و زهره\n(۲) ماه، عطارد، زهره و خورشید\n(۳) خورشید، ماه، عطارد و زهره\n(۴) ماه، زهره، خورشید و عطارد","options":["ماه، خورشید، عطارد و زهره","ماه، عطارد، زهره و خورشید","خورشید، ماه، عطارد و زهره","ماه، زهره، خورشید و عطارد"],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/tajrobi_nobat1_143.jpg"],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_143","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
