INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('78a509c9eb216a9632d58bc6214ed109','persian-konkur-1404-first-physics-1','physics','فیزیک — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_47","subjectId":"physics","chapter":"فیزیک — کنکور ۱۴۰۴","prompt":"از یک سیم راست بلند، جریان ثابت I می گذرد. سیم، عمود بر صفحه ی کاغذ و جریان آن به طرف بیرون صفحه است. خطوط میدان مغناطیسی در کدام شکل، درست نمایش داده شده است؟","options":["۱","۲","۳","۴"],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/tajrobi_nobat1_47.jpg"],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_47","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5ad6cc3dcf18437487006fb327bc25ea','persian-konkur-1404-first-physics-1','physics','فیزیک — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_49","subjectId":"physics","chapter":"فیزیک — کنکور ۱۴۰۴","prompt":"کدام مورد نادرست است؟\n۱) بارومتر، وسیله‌ای ساده برای اندازه‌گیری فشار جو است.\n۲) فشار در یک عمق معین از مایع به جهت گیری سطحی که فشار به آن وارد می‌شود، بستگی دارد.\n۳) یکی از وسیله‌های ساده برای اندازه‌گیری فشار یک شاره محصور، فشارسنج شکل است که مانومتر نامیده می‌شود.\n۴) در آزمایش توریچلی، برای لوله‌های غیرمویین، اگر سطح مقطع و طول لوله‌ها متفاوت باشد، ارتفاع ستون جیوه تغییر نمی‌کند.","options":["۱","۲","۳","۴"],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_49","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('581c465d85cb2cfde043aa54e0aa0ec7','persian-konkur-1404-first-physics-1','physics','فیزیک — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat1_60","subjectId":"physics","chapter":"فیزیک — کنکور ۱۴۰۴","prompt":"مطابق شکل زیر، پرتو نوری به آینه تخت (۱) می‌تابد و در نهایت از آینه تخت (۲) بازتاب می‌شود. زاویه بین دو آینه چند درجه است؟","options":["۱۴۰ (۱)","۱۳۰ (۲)","۱۲۰ (۳)","۱۰۰ (۴)"],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت اول)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/tajrobi_nobat1_60.jpg"],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت اول — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat1_60","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
