INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a71d54e04f4dfa70937bbb1dcb87336b','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_1","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در ارتباط با تمام یا بخشی از لایه خارجی پرده جنب ،انسان کدام مورد درست است؟\n1) توسط بخش جانبی اسکلت بدن احاطه میشود.\n2) در مجاورت بنداره (اسفنکتر) انتهای معده است.\n3) به ساختاری اسفنج گونه و کشسان چسبیده است.\n4) در نزدیکی استخوانی است که با استخوان کتف مفصل میشود.","options":["توسط بخش جانبی اسکلت بدن احاطه میشود.","در مجاورت بنداره (اسفنکتر) انتهای معده است.","به ساختاری اسفنج گونه و کشسان چسبیده است.","در نزدیکی استخوانی است که با استخوان کتف مفصل میشود."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_1","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('cd9cf08ebd855f5f6ebfed88e9c65078','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_2","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"با توجه به اطلاعات کتاب درسی درباره چشم انسان یاخته های گیرنده‌ای که در نور کم تحریک می‌شوند نسبت به یاخته‌های گیرنده‌ای که در نور زیاد تحریک می‌شوند، چه مشخصه‌ای دارند؟ (درنظر بگیرید در هر گیرنده نور، قطعه‌ای که میان محل هسته و محل قرارگیری ماده حساس به نور است، قطعه داخلی و بخش حاوی ماده حساس به نور، قطعه خارجی نامیده می‌شود.)\n1) قطعه داخلی قطورتری دارند.\n2) هسته آنها بسیار بزرگتر است.\n3) بخش خارجی بلندتری دارند.\n4) در لکه زرد به میزان فراوانتری یافت می‌شوند.","options":["قطعه داخلی قطورتری دارند.","هسته آنها بسیار بزرگتر است.","بخش خارجی بلندتری دارند.","در لکه زرد به میزان فراوانتری یافت می‌شوند."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_2","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('7ae8dfb1674a3edaa8892c2920e069d2','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_3","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام مورد نادرست است؟\n1) واتسون و کریک با بررسی نقاط تیره در مرکز تصویر حاصل از پرتو ایکس، مدل مولکولی دنا را ساختند.\n2) مزلسون و استال چگونگی همانند سازی و توزیع دنا را بین یاخته های تکثیر یافته بررسی کردند.\n3) دلیل برابری نوکلئوتیدها در دنای جانداران برای چارگاف نامشخص بود.\n4) ابعاد مولکولهای دنا برای ویلکینز و فرانکلین قابل تشخیص بود.","options":["واتسون و کریک با بررسی نقاط تیره در مرکز تصویر حاصل از پرتو ایکس، مدل مولکولی دنا را ساختند.","مزلسون و استال چگونگی همانند سازی و توزیع دنا را بین یاخته های تکثیر یافته بررسی کردند.","دلیل برابری نوکلئوتیدها در دنای جانداران برای چارگاف نامشخص بود.","ابعاد مولکولهای دنا برای ویلکینز و فرانکلین قابل تشخیص بود."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_3","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('236e7f502bd070b7f47cea7f9ba8dd8b','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_4","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب ،درسی در خصوص یاخته‌هایی که قادرند ماده اصلی ایجادکننده علایم شایع حساسیت را تولید کنند کدام مورد زیر درست است؟\n1) همه آنها درشت خوار هستند.\n2) همه آنها سیتوپلاسمی با دانه‌های روشن دارند.\n3) فقط بعضی از آنها دارای هسته چند قسمتی هستند.\n4) فقط بعضی از آنها در شرایط طبیعی در بافتها حضور دارند.","options":["همه آنها درشت خوار هستند.","همه آنها سیتوپلاسمی با دانه‌های روشن دارند.","فقط بعضی از آنها دارای هسته چند قسمتی هستند.","فقط بعضی از آنها در شرایط طبیعی در بافتها حضور دارند."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_4","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('cb579f14aadd6a0033ff101503318d9f','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_5","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"با گذشت زمان و طی سالیان ،متمادی دوگونه میگوی هم نژاد هر یک به صورت جمعیتی ،کوچک پس از ایجاد پدیده کوه زایی به وجود آمدند با توجه به تعریفی که ارنست مایر از گونه ارائه ،داد کدام مورد زیر میتواند درست باشد؟\n1) همه عواملی که میتوانستند جمعیت اولیه را از تعادل خارج ،کنند فعال ماندند.\n2) همه عوامل مؤثر در گونه زایی دگره (الل) یا دگره‌هایی را به جمعیت افزودند.\n3) با گذر زمان، عواملی باعث تداوم گوناگونی در جمعیت ها شد.\n4) امکان آمیزش موفقیت آمیز بین افراد دو جمعیت وجود دارد.","options":["همه عواملی که میتوانستند جمعیت اولیه را از تعادل خارج ،کنند فعال ماندند.","همه عوامل مؤثر در گونه زایی دگره (الل) یا دگره‌هایی را به جمعیت افزودند.","با گذر زمان، عواملی باعث تداوم گوناگونی در جمعیت ها شد.","امکان آمیزش موفقیت آمیز بین افراد دو جمعیت وجود دارد."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_5","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
