INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('8ea87f43cdc82d6f440d84f11b284643','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_7","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در ارتباط با یکی از پرده های جنینی که به دیواره رحم انسان میچسبد کدام مورد را میتوان بیان نمود؟\n1) خون جنین مستقیماً از رگهای آن خارج و به درون حفره های اطراف زوائد انگشتی وارد میشود.\n2) منشأ آن، یاخته هایی است که فرایند جایگزینی توسط آنها انجام شد.\n3) حاوی رگهایی است که خون مادر هم در آن جریان دارد.\n4) باعث فعالیت جسم زرد تا انتهای دوره بارداری میشود.","options":["خون جنین مستقیماً از رگهای آن خارج و به درون حفره های اطراف زوائد انگشتی وارد میشود.","منشأ آن، یاخته هایی است که فرایند جایگزینی توسط آنها انجام شد.","حاوی رگهایی است که خون مادر هم در آن جریان دارد.","باعث فعالیت جسم زرد تا انتهای دوره بارداری میشود."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_7","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('8d285c4312068e9c1b968b9260bcc37b','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_8","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام مورد زیر در ارتباط با جلبک قهوه ای نادرست است؟\n1) تعداد جایگاههای همانندسازی بسته به نیاز جاندار قابل تنظیم است.\n2) دقت بالای همانندسازی دنا منحصراً به توانایی ویرایش دنابسپاراز وابسته است.\n3) در یک مرحله از اینترفاز، هر بخش از دنا جهت همانندسازی، فقط یکبار باز میشود.\n4) پیشرفت همانندسازی در بخشهای باز شده دنای یک فامتن (کروموزوم) میتواند یکسان باشد.","options":["تعداد جایگاههای همانندسازی بسته به نیاز جاندار قابل تنظیم است.","دقت بالای همانندسازی دنا منحصراً به توانایی ویرایش دنابسپاراز وابسته است.","در یک مرحله از اینترفاز، هر بخش از دنا جهت همانندسازی، فقط یکبار باز میشود.","پیشرفت همانندسازی در بخشهای باز شده دنای یک فامتن (کروموزوم) میتواند یکسان باشد."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_8","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5126e988e4aaa86195fbbbb11be5f82c','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_9","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در انسان، کدام عبارت در ارتباط با اندامهای دستگاه گوارش موجود در شکم درست است؟\n1) فقط بعضی از اندامهایی که به میان بند (دیافراگم) نزدیک هستند میتوانند نوعی ترکیب یونی بسازند.\n2) هر اندامی که توانایی تولید نوعی پلی ساکارید ذخیره ای را دارد، نوعی آنزیم را به شیره گوارشی می افزاید.\n3) هر یاخته از اندامی که توانایی تولید بیکربنات را دارد، نوعی گلیکوپروتئین سازنده ماده مخاطی تولید میکند.\n4) فقط بعضی از اندامهایی که ماهیچه های حلقوی جهت تنظیم عبور مواد دارند، میتوانند نوعی آنزیم گوارشی ترشح کنند.","options":["فقط بعضی از اندامهایی که به میان بند (دیافراگم) نزدیک هستند میتوانند نوعی ترکیب یونی بسازند.","هر اندامی که توانایی تولید نوعی پلی ساکارید ذخیره ای را دارد، نوعی آنزیم را به شیره گوارشی می افزاید.","هر یاخته از اندامی که توانایی تولید بیکربنات را دارد، نوعی گلیکوپروتئین سازنده ماده مخاطی تولید میکند.","فقط بعضی از اندامهایی که ماهیچه های حلقوی جهت تنظیم عبور مواد دارند، میتوانند نوعی آنزیم گوارشی ترشح کنند."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_9","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e358494227ef223bcdd5ebe75ee727f4','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_10","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی، در تنه استخوان بازوی انسان، به غیر از مجرای مرکزی استخوان، مجاری دیگری وجود دارد که محتوی رگهای خونی و لنفیاند. کدام مورد دربارۀ این مجاری درست است؟\n1) همۀ آنها با تیغههای استخوانی مجاورت دارند.\n2) فقط بعضی از آنها حاوی مجموعه ای از رشتههای عصبی هستند.\n3) همۀ آنها حاوی یاخته های چربی و مقادیر فراوانی یاختههای بنیادی میلوئیدیاند.\n4) فقط بعضی از آنها دیواره ای از جنس بافت پیوندی دارند و با مجرای مرکزی استخوان نیز موازی هستند.","options":["همۀ آنها با تیغههای استخوانی مجاورت دارند.","فقط بعضی از آنها حاوی مجموعه ای از رشتههای عصبی هستند.","همۀ آنها حاوی یاخته های چربی و مقادیر فراوانی یاختههای بنیادی میلوئیدیاند.","فقط بعضی از آنها دیواره ای از جنس بافت پیوندی دارند و با مجرای مرکزی استخوان نیز موازی هستند."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_10","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ef02e2f8a146965a6ec205f921149bcc','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_11","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"با توجه به اطلاعات کتاب درسی درباره تنظیم مثبت و منفی در باکتری اشرشیاکلای، کدام مورد دربارۀ توالی های تنظیمی مؤثر در شروع رونویسی نادرست است؟\n1) فقط یکی از آنها در مجاورت نخستین ژن قرار دارد.\n2) هر دوی آنها، بر ساختار اول محصول آخرین ژن بی تأثیرند.\n3) فقط یکی از آنها، باعث میشود تا رنا بسپاراز اولین نوکلئوتید رمزه را در رشتۀ الگو به طور دقیق پیدا کند.\n4) هر دوی آنها، میتوانند به مولکولی متصل شوند که یک یا چند زنجیره بلند و بدون شاخه دارد.","options":["فقط یکی از آنها در مجاورت نخستین ژن قرار دارد.","هر دوی آنها، بر ساختار اول محصول آخرین ژن بی تأثیرند.","فقط یکی از آنها، باعث میشود تا رنا بسپاراز اولین نوکلئوتید رمزه را در رشتۀ الگو به طور دقیق پیدا کند.","هر دوی آنها، میتوانند به مولکولی متصل شوند که یک یا چند زنجیره بلند و بدون شاخه دارد."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_11","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('b18393d93ded5f8e2d8a78e3437c2ff2','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_12","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در بخشی از کتاب درسی، نمودار مزیت زندگی گروهی نوعی جانور نشان داده شده، چند مورد برای تکمیل عبارت زیر مناسب است؟\n«این جانور و ..................................................... دارند.»\nالف - شیر کوهی، اندامهای همتا\nب - پشه، اندامهای آنالوگ\nج - خفاش، دیواره کاملی بین دو بطن\nد - ملخ، بخش حجیمی در انتهای مری","options":["1 (1)","2 (2)","3 (3)","4 (4)"],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_12","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('1a541a76cf03e688dd66696f70ef4c98','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_13","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص شبکه هادی قلب یک انسان سالم، کدام مورد نادرست است؟\n1) در حالتی که نیمی از دریچه های قلب بسته هستند، ممکن است پیام الکتریکی از گره اول به سمت گره دوم منتقل شود.\n2) در زمانی که پیام الکتریکی از طریق گره کوچکتر در سراسر دهلیز منتشر میشود، دریچه سه لختی باز است.\n3) قبل از اینکه تمام دریچه های قلبی بسته شوند، پیام الکتریکی در دیواره بین دو بطن منتشر شده است.\n4) در زمانی که پیام الکتریکی به سمت نوک قلب منتشر میشود، دریچه دولختی باز است.","options":["در حالتی که نیمی از دریچه های قلب بسته هستند، ممکن است پیام الکتریکی از گره اول به سمت گره دوم منتقل شود.","در زمانی که پیام الکتریکی از طریق گره کوچکتر در سراسر دهلیز منتشر میشود، دریچه سه لختی باز است.","قبل از اینکه تمام دریچه های قلبی بسته شوند، پیام الکتریکی در دیواره بین دو بطن منتشر شده است.","در زمانی که پیام الکتریکی به سمت نوک قلب منتشر میشود، دریچه دولختی باز است."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_13","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('b2ee8f13dcabb6a7cca9b90cbf992185','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_16","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص فناوریهای نوین زیستی، کدام مورد زیر نادرست است؟\n1) برای تولید گیاه پنبه مقاوم به آفت، ژن مربوط به سم، ابتدا در خارج از گیاه تکثیر میشود.\n2) در علم بیوانفورماتیک، فرضیههای قابل آزمون بدون نیاز به بررسی دادهها انتخاب میشوند.\n3) برای تشخیص بیماری ایدز قبل از بروز علایم اولیه، دنای موجود در خون فرد را استخراج میکنند.\n4) به منظور تولید واکسن به روش مهندسی ژنتیک، از اطلاعات ژنتیکی عامل بیماریزا استفاده میشود.","options":["برای تولید گیاه پنبه مقاوم به آفت ژن مربوط به سم ابتدا در خارج از گیاه تکثیر میشود.","در علم بیوانفورماتیک فرضیه های قابل آزمون بدون نیاز به بررسی داده ها انتخاب میشوند.","برای تشخیص بیماری ایدز قبل از بروز علایم اولیه دنای موجود در خون فرد را استخراج میکنند.","به منظور تولید واکسن به روش مهندسی ژنتیک از اطلاعات ژنتیکی عامل بیماری زا استفاده میشود."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_16","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('81c102888ff2ad82bb4e8ca5fef36df8','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_17","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"چند مورد، در ارتباط با تنه چوبی شده درخت سیب، صحیح است؟\nالف - هر دو نوع کامبیوم، در تشکیل پوست درخت نقش اصلی را دارند.\nب - یافته های همراه در منطقه پوست درخت یافت میشوند.\nج - در منطقه پوست بعضی از یاخته ها به تدریج نسبت به گازها نفوذناپذیر میشوند.\nد - در مجاورت پوست درخت، یاختههای به هم فشردهای قرار دارند که به طور مداوم تکثیر میشوند.","options":["1","2","3","4"],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_17","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a837b43d490b5d702417a32fb14c2dac','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_19","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی کدام عبارت درباره پوشش دولایه ای تخمک گیاه کدو نادرست است؟\n1) به یک گل ناکامل تعلق دارد.\n2) پس از انجام عمل لقاح باقی میماند.\n3) به طور کامل یاختههای بافت خورش را احاطه میکند.\n4) از طریق پایهای به دیواره بخش حجیم برچه متصل است.","options":["به یک گل ناکامل تعلق دارد.","پس از انجام عمل لقاح باقی میماند.","به طور کامل یاخته های بافت خورش را احاطه میکند.","از طریق پایه ای به دیواره بخش حجیم برچه متصل است."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_19","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('2012cca5d2ca43bb8432c0c246dd6044','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_20","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مقدار مشخصی پپسین از بدن موجود زنده استخراج شده و به صورت خالص درآمده و فعالیت آن در محیط آزمایشگاه مورد بررسیهای مکرر قرار گرفته است. کدام مورد، دربارهٔ این آنزیم درست است؟\n(۱) پیش‌ماده‌هایی دارد که از نظر نوع، ترتیب و تعداد واحدهای سازنده می‌توانند متفاوت باشند.\n(۲) تحت هر شرایط، حداکثر سرعت انجام واکنش را به مقدار یکسانی می‌رساند.\n(۳) می‌تواند واکنش‌های انجام‌نشدنی را با کاهش انرژی فعالسازی تسریع کند.\n(۴) در محیط قلیایی می‌تواند به حداکثر فعالیت خود برسد.","options":["پیش‌ماده‌هایی دارد که از نظر نوع، ترتیب و تعداد واحدهای سازنده می‌توانند متفاوت باشند.","تحت هر شرایط، حداکثر سرعت انجام واکنش را به مقدار یکسانی می‌رساند.","می‌تواند واکنش‌های انجام‌نشدنی را با کاهش انرژی فعالسازی تسریع کند.","در محیط قلیایی می‌تواند به حداکثر فعالیت خود برسد."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_20","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('79892005e7c6639d27af3b8502fe5600','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_21","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"با توجه به بخش‌های مورد نظر، کدام مورد درست است؟","options":["بخش ۲ همانند بخش ۱، دیواره‌ای دارد که یاخته‌های پوششی آن با فاصله زیادی از یکدیگر قرار گرفته‌اند.","در بخش ۲ نسبت به بخش ۱، میزان ماده دفعی نیتروژن‌دار آلی کمتر است.","با انقباض بخش ۲، جریان خون کلافک (گلومرول) کاهش می‌یابد.","بخش ۱، در ادامه کلافک (گلومرول) را می‌سازد."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/tajrobi_nobat2_21.jpg"],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_21","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('75d88cc34af61f5c81979cbebd240a54','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_22","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی، در نوعی جانور بی‌مهره، مویرگ‌ها در کنار یاخته‌ها قرار دارند و با کمک آب میان‌بافتی، تبادل مواد غذایی، دفعی و گازها به انجام می‌رسد. کدام عبارت، در مورد این جانور نادرست است؟\n(۱) همانند قورباغه، از طریق شبکه مویرگی زیرپوستی تنفس می‌کند.\n(۲) همانند کرم کدو، هر دو نوع دستگاه تولیدمثلی نر و ماده را دارد.\n(۳) همانند پلاناریا، از بی‌مهرگان آزادزی محسوب می‌شود.\n(۴) همانند کرم کدو، مجهز به دهان و لولهٔ گوارش است.","options":["همانند قورباغه، از طریق شبکه مویرگی زیرپوستی تنفس می‌کند.","همانند کرم کدو، هر دو نوع دستگاه تولیدمثلی نر و ماده را دارد.","همانند پلاناریا، از بی‌مهرگان آزادزی محسوب می‌شود.","همانند کرم کدو، مجهز به دهان و لولهٔ گوارش است."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_22","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5469631d6dcbd8ad4cf3606af289f2e6','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_23","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص عضلهٔ دوسر بازوی یک فرد سالم، کدام موارد زیر درست است؟\nالف- از یک انتها به استخوان زند زیرین متصل است.\nب- از طریق دو زردپی به ناحیهٔ شانه اتصال دارد.\nج- آنزیمی دارد که با استفاده از اکسیژن و کراتین فسفات، کراتین می‌سازد.\nد- اغلب با اکسایش نوعی بسپار آمین‌دار، انرژی موردنیاز خود را به دست می‌آورد.","options":["«الف» و «ب»","«الف»، «ج» و «د»","«ب»، «ج» و «د»","«الف»، «ب»، «ج» و «د»"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_23","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('7ad7ada655f7c8ce8024aa4d29e6c8de','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_24","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام مورد، دربارهٔ گیرنده‌های شنوایی گوش انسان، نادرست است؟\n(۱) به طور یکنواخت در لابهلای یاخته‌های پوششی توزیع شده‌اند.\n(۲) ناقلین عصبی را در مجرای میانی بخش حلزونی آزاد می‌کنند.\n(۳) همانند نوعی گیرندهٔ حواس پیکری در اثر ارتعاش تحریک می‌شوند.\n(۴) رشته‌های عصبی مرتبط با آنها، از کنار یاخته‌های پوششی عبور می‌کند.","options":["به طور یکنواخت در لابهلای یاخته‌های پوششی توزیع شده‌اند.","ناقلین عصبی را در مجرای میانی بخش حلزونی آزاد می‌کنند.","همانند نوعی گیرندهٔ حواس پیکری در اثر ارتعاش تحریک می‌شوند.","رشته‌های عصبی مرتبط با آنها، از کنار یاخته‌های پوششی عبور می‌کند."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_24","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e56cfed7b01e1ec3953987658dc558ed','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_25","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام عبارت در خصوص زندگی گروهی زنبورهای عسل، درست است؟\n(۱) همه زنبورهای کارگر، از تخمک بارورنشده ملکه به وجود می‌آیند.\n(۲) زنبورهایی که در جمع‌آوری شهد و گردهٔ گل‌ها نقش دارند، ماده هستند.\n(۳) زنبور یابنده همواره محل دقیق منبع غذایی را به زنبورهای کارگر اطلاع می‌دهد.\n(۴) گیرنده‌های نوری زنبورهای کارگر، منحصراً پرتوهای فرابنفش را دریافت می‌کنند.","options":["همه زنبورهای کارگر، از تخمک بارورنشده ملکه به وجود می‌آیند.","زنبورهایی که در جمع‌آوری شهد و گردهٔ گل‌ها نقش دارند، ماده هستند.","زنبور یابنده همواره محل دقیق منبع غذایی را به زنبورهای کارگر اطلاع می‌دهد.","گیرنده‌های نوری زنبورهای کارگر، منحصراً پرتوهای فرابنفش را دریافت می‌کنند."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_25","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('57ec92de5b743e6184144bde0aec12bc','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_26","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در کشاورزی، از نوعی تنظیم کننده رشد گیاهی، جهت ممانعت از ریزش برگ استفاده می‌شود. کدام دو نقش زیر به این هورمون اختصاص دارد؟\n(۱) کنترل علف‌های هرز و بالا بردن کیفیت میوه‌ها\n(۲) سریع خارج کردن جوانه‌های برنج از آب و زرد نمودن پوست موز نارس\n(۳) پر شاخه و برگ نمودن گیاه توتون و به خواب بردن بذرهای سیب‌زمینی\n(۴) به تعویق انداختن گلدهی گیاه زنبق و تأخیر فرایند پیری در گل داوودی","options":["کنترل علف‌های هرز و بالا بردن کیفیت میوه‌ها","سریع خارج کردن جوانه‌های برنج از آب و زرد نمودن پوست موز نارس","پر شاخه و برگ نمودن گیاه توتون و به خواب بردن بذرهای سیب‌ زمینی","به تعویق انداختن گلدهی گیاه زنبق و تأخیر فرایند پیری در گل داوودی"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_26","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('9fc9534e1331d273f174d3b8df31e2a4','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_27","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در ارتباط با فرایند پروتئین‌سازی در اشرشیاکلای، کدام مورد غیرممکن است؟\n(۱) در زمانی که رشته پلی‌پپتیدی از رناتن (ریبوزوم) خارج می‌شود، جایگاه E رناتن خالی است.\n(۲) پس از اینکه اتصال tRNA و توالی آمینواسیدها قطع شد، رناتن (ریبوزوم) به اندازه یک رمزه جابه‌جا می‌شود.\n(۳) زمانی که جایگاه E رناتن (ریبوزوم) در حال خالی شدن است، tRNA حامل توالی آمینواسیدها در جایگاه A قرار دارد.\n(۴) در زمانی که زیر واحد بزرگ رناتن (ریبوزوم) به زیر واحد کوچک آن متصل می‌شود، جایگاه E و A رناتن خالی است.","options":["در زمانی که رشته پلی‌پپتیدی از رناتن (ریبوزوم) خارج می‌شود، جایگاه E رناتن خالی است.","پس از اینکه اتصال tRNA و توالی آمینواسیدها قطع شد، رناتن (ریبوزوم) به اندازه یک رمزه جابه‌جا می‌شود.","زمانی که جایگاه E رناتن (ریبوزوم) در حال خالی شدن است، tRNA حامل توالی آمینواسیدها در جایگاه A قرار دارد.","در زمانی که زیر واحد بزرگ رناتن (ریبوزوم) به زیر واحد کوچک آن متصل می‌شود، جایگاه E و A رناتن خالی است."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_27","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e3816522027fd4b8318516d5a534fcc1','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_28","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام عبارت درست است؟\n(۱) همة جاندارانی که یون آمونیوم را مستقیماً از محیط دریافت می‌کنند، شیمیوسنتز کننده‌ هستند.\n(۲) در میکوریزا، رشته‌های ظریف قارچ‌ها در فضای بین یاخته‌های پوست ریشة گیاهان نفوذ می‌کند.\n(۳) هنگام بارندگی‌های شدید، گیاخاک (هوموس) می‌تواند به میزان زیاد یون‌های نیترات را حفظ نماید.\n(۴) نیتروژن تثبیت‌شده توسط ریزجانداران (میکروارگانیسم‌ها)، فقط پس از مرگ آن‌ها برای گیاهان قابل دسترس است.","options":["همة جاندارانی که یون آمونیوم را مستقیماً از محیط دریافت می‌کنند، شیمیوسنتز کننده‌ هستند.","در میکوریزا، رشته‌های ظریف قارچ‌ها در فضای بین یاخته‌های پوست ریشة گیاهان نفوذ می‌کند.","هنگام بارندگی‌های شدید، گیاخاک (هوموس) می‌تواند به میزان زیاد یون‌های نیترات را حفظ نماید.","نیتروژن تثبیت‌شده توسط ریزجانداران (میکروارگانیسم‌ها)، فقط پس از مرگ آن‌ها برای گیاهان قابل دسترس است."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_28","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('13e6b4ae42e54bfccdba9a776ab8d442','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_29","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در خصوص یاختة عصبی حسی مربوط به انعکاس عقب کشیدن دست انسان، چند مورد زیر درست است؟\nالف - تعداد آن‌ها کمتر از تعداد یاخته‌های عصبی حرکتی است.\nب - طول دارینه (دندریت) آن، از طول آسه (آکسون) اش بیشتر است.\nج ـ دارینة آن و آسة یاختة عصبی حرکتی، در تمام طول در مجاورت یکدیگر قرار دارند.\nد ـ از یک نقطة جسم یاخته‌ای، آن زوائدای خارج و سپس دوشاخه شده است.\n(۱)\n(۲)\n(۳)\n(۴)\n۱\n۲\n۳\n۴","options":["۱","۲","۳","۴"],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_29","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('6eb6b1ec37cf740674129ae4cffecca1','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_31","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام مورد دربارة دستگاه تولیدمثلی یک مرد جوان، درست است؟\n(۱) زامه (اسپرم) ها پس از تولید، ابتدا توسط یک مجرای واحد به لوله‌ای پیچیده و طویل وارد می‌شوند.\n(۲) غده‌ای که در پشت راست روده قرار دارد، انرژی لازم برای فعالیت زامه (اسپرم) ها را فراهم می‌کند.\n(۳) مجرای زامه بر از پشت بخش انتهایی میزنای عبور کرده و ترشحات غده وزیکول سمینال را دریافت می‌کند.\n(۴) مجرای محتوی زامه (اسپرم) ها و مایعی غنی از فروکتوز، در درون نوعی اندام، به میزراه متصل می‌شود.","options":["زامه (اسپرم) ها پس از تولید، ابتدا توسط یک مجرای واحد به لوله‌ای پیچیده و طویل وارد می‌شوند.","غده‌ای که در پشت راست روده قرار دارد، انرژی لازم برای فعالیت زامه (اسپرم) ها را فراهم می‌کند.","مجرای زامه بر از پشت بخش انتهایی میزنای عبور کرده و ترشحات غده وزیکول سمینال را دریافت می‌کند.","مجرای محتوی زامه (اسپرم) ها و مایعی غنی از فروکتوز، در درون نوعی اندام، به میزراه متصل می‌شود."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_31","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('2553adb7c484145fedcb70ff03bf3166','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_32","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"فرد ایستاده‌ای را در نظر بگیرید که پاهایش را جفت کرده، دستانش را آویزان نموده و کف آنها را به سمت جلو قرار داده است. به‌طور معمول کدام مورد، دربارة این فرد نادرست است؟ (در نظر بگیرید منظور از سر استخوان زند زبرین و زیرین، هر یک بخشی است که با استخوان بازو مفصل تشکیل می‌دهد).\n(۱) استخوان‌های قطورتر دو ساق پا نسبت به استخوان‌های نازک‌تر آن دو، به یکدیگر نزدیک‌ترند.\n(۲) استخوان زند زیرین نسبت به استخوان زند زبرین به بخش محوری اسکلت نزدیک‌تر است.\n(۳) سر استخوان زند زبرین نسبت به سر استخوان زند زیرین در موقعیت بالاتری قرار دارد.\n(۴) استخوان قطورتر ساق پا، نسبت به استخوان بازو طول بیشتری دارد.","options":["استخوان‌های قطورتر دو ساق پا نسبت به استخوان‌های نازک‌تر آن دو، به یکدیگر نزدیک‌ترند.","استخوان زند زیرین نسبت به استخوان زند زبرین به بخش محوری اسکلت نزدیک‌تر است.","سر استخوان زند زبرین نسبت به سر استخوان زند زیرین در موقعیت بالاتری قرار دارد.","استخوان قطورتر ساق پا، نسبت به استخوان بازو طول بیشتری دارد."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_32","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('92df42d067313b99062fe8ef2736e7c5','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_33","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با مطالب کتاب درسی همه فرایندهای آزاد شدن انرژی از گلوکز را که در گیاهان می‌تواند رخ دهد، درنظر بگیرید. در کدام مورد، تولید یون مثبت غیرممکن است؟\n1) در واکنشی که پیش‌ماده، قندی دوفسفاته و فرآورده‌ها قندهای تک‌فسفاته هستند.\n2) در واکنشی که فرآورده نسبت به پیش‌ماده یک گروه فسفات بیشتر دارد.\n3) در واکنشی که فرآورده نسبت به پیش‌ماده، اتم اکسیژن کمتری دارد.\n4) در واکنشی که پیش‌ماده و فرآورده هر دو سه‌کربنی هستند.","options":["در واکنشی که پیش‌ماده، قندی دوفسفاته و فرآورده‌ها قندهای تک‌فسفاته هستند.","در واکنشی که فرآورده نسبت به پیش‌ماده یک گروه فسفات بیشتر دارد.","در واکنشی که فرآورده نسبت به پیش‌ماده، اتم اکسیژن کمتری دارد.","در واکنشی که پیش‌ماده و فرآورده هر دو سه‌کربنی هستند."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_33","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('b75f5deae197d722b12c8cfe3b57f9f5','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_34","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n«به‌طور معمول، همه یاخته‌هایی از مراحل تخمک‌زایی که در تخمدان\n1) یک خانم جوان به‌وجود می‌آیند، دنای سیتوپلاسمی یکسانی دارند\n2) یک جنین دختر یافت می‌شوند، دو مجموعه فامتن (کروموزوم) دارند\n3) یک دختر جوان یافت می‌شوند، در مجاورت با ساختاری مخاطی و مژک‌دار قرار خواهند گرفت\n4) یک نوزاد دختر وجود دارند، دارای چهارتایه (تتراد)هایی هستند که همگی در وسط یاخته بر روی رشته‌های دوک ردیف شده‌اند","options":["یک خانم جوان به‌وجود می‌آیند، دنای سیتوپلاسمی یکسانی دارند","یک جنین دختر یافت می‌شوند، دو مجموعه فامتن (کروموزوم) دارند","یک دختر جوان یافت می‌شوند، در مجاورت با ساختاری مخاطی و مژک‌دار قرار خواهند گرفت","یک نوزاد دختر وجود دارند، دارای چهارتایه (تتراد)هایی هستند که همگی در وسط یاخته بر روی رشته‌های دوک ردیف شده‌اند"],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_34","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('1091dfc2a0a0f9b8769384ab4928f9d9','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_35","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"دو بخش از هیپوتالاموس انسان را در نظر بگیرید که هورمون‌های بخش پسین هیپوفیز را می‌سازند. در ارتباط با بخشی که نسبت به بخش دیگر در موقعیت پایین‌تری قرار دارد، چند مورد زیر درست است؟ (درنظر بگیرید فرد به حالت ایستاده است و سر، گردن و تنه او در یک راستا قرار دارند.)\nالف ـ در مقایسه با بخش دیگر، با آسه (آکسون)هایی مرتبط است که طول بسیار بلندتری دارد.\nب ـ پایانه‌های آسه (آکسون)های مرتبط با آن در ساقه هیپوفیز قرار دارد.\nج ـ جسم یاخته‌های عصبی مرتبط با آن در درون استخوان کف جمجمه است.\nد ـ در مقایسه با بخش دیگر، با آسه (آکسون)هایی ارتباط دارد که به هیپوفیز پیشین نزدیک‌تر است.\n1) 1\n2) 2\n3) 3\n4) 4","options":["1","2","3","4"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_35","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ad24f29abff6b85b41dc7e89051367a1','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_36","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"با توجه به مطالب کتاب درسی، کدام عبارت درباره یک نوجوان سالم (N)، همان فرد ۱۰ روز پس از آخرین مصرف کوکائین (T) و همان فرد ۱۰۰ روز پس از آخرین مصرف این ماده مخدر (H)، نادرست است؟\n1) در حالت T نسبت به حالت N، احتمال افسردگی بیشتر است.\n2) در حالت H، توانایی قضاوت و یادگیری کمتر از حالت N است.\n3) در حالت H میزان فعالیت بخش پیشین مغز به اندازه حالت N رسیده است.\n4) در حالت H نسبت به حالت T، مشکلات احتمالی بینایی می‌تواند رو به بهبود باشد.","options":["در حالت T نسبت به حالت N، احتمال افسردگی بیشتر است.","در حالت H، توانایی قضاوت و یادگیری کمتر از حالت N است.","در حالت H میزان فعالیت بخش پیشین مغز به اندازه حالت N رسیده است.","در حالت H نسبت به حالت T، مشکلات احتمالی بینایی می‌تواند رو به بهبود باشد."],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_36","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
