INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('d3e476be8c1e047e97a47f18178826c4','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_40","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی، نوعی رفتار فقط در دورهٔ خاصی از زندگی جوجه غازها (تازه از تخم درآمده)، دیده می‌شود. کدام عبارت در مورد این رفتار، درست است؟\n1) می‌تواند باعث افزایش موفقیت تولید مثلی مادر شود.\n2) باعث می‌شود تا جوجه‌ها تنها با پرندهٔ هم‌گونهٔ خود، ارتباط برقرار کنند.\n3) به‌طور کامل هنگام تولد در جوجه‌ها ایجاد شده و رفتاری کاملاً غریزی است.\n4) نوعی رفتار خوگیری است و امکان سازگار شدن جوجه‌ها را با محیط فراهم می‌آورد.","options":["1","2","3","4"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_40","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e02b2624ca8017b57408f3f0a1ec4b29','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_41","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در ارتباط با غدهٔ فوق کلیه یک خانم جوان، چند مورد زیر می‌تواند درست باشد؟\nالف- با پرکاری بخش قشری این غده، صدا به صورت بم درآمده و تعداد موهای صورت بیشتر می‌شود.\nب- با کم‌کاری بخش قشری این غده، غلظت گویچه‌های قرمز خون بالا می‌رود و میزان برون‌ده قلبی کم می‌شود.\nج- با پرکاری بخش قشری این غده، عضلات و استخوان‌ها ضعیف می‌شود.\nد- با کم‌کاری بخش مرکزی این غده، توان فرد برای مقابله با شرایط استرس‌زا کم می‌شود.\n1) 1\n2) 2\n3) 3\n4) 4","options":["1","2","3","4"],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_41","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('9a4fceaec6d9f83f822acfaab8fa2372','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_42","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"مطابق با اطلاعات کتاب درسی، در خصوص پنج ساختاری که مراحل فشرده شدن فامتن (کروموزوم) را نشان می‌دهد، کدام مورد نادرست است؟\n1) در ساختار دوم و پنجم، مارپیچ دورشته‌ای وجود دارد.\n2) در ساختار سوم و چهارم، ساختارهای فنری شکل به وجود آمده‌اند.\n3) در ساختار اول و دوم، وجود میان‌کنش پروتئین‌های ساختاری ضروری است.\n4) در ساختار چهارم و پنجم، واحدهای تکراری غیرمجاور، به یکدیگر نزدیک شده‌اند.","options":["1","2","3","4"],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_42","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('2d23187554580ac935f672eacb5322a6','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_43","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"با فرض طبیعی بودن مقدار اکسیژن محیط و در نظر گرفتن هر دو صفت هموفیلی و داسی شدن گویچه‌های قرمز، کدام مورد می‌تواند نشانگر حالتی باشد که فقط یک نوع ژن‌نمود (ژنوتیپ) برای فرزند دختر محتمل است و این دختر فقط رخ نمود (فنوتیپ) مادر (نه رخ‌نمود پدر) را نشان خواهد داد؟\n1) مادر بیمار و پدر بیمار\n2) مادر سالم و پدر بیمار\n3) مادر بیمار و پدر سالم\n4) مادر سالم و پدر سالم","options":["1","2","3","4"],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_43","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('400708b13bbbfa8d8c9dd910558d28b1','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_44","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"کدام ویژگی را می‌توان برای هر نیمکرهٔ موجود در مغز انسان در نظر گرفت؟\n1) در بخش خارجی آن، جسم یاخته‌های عصبی و رشته‌های عصبی بدون میلین وجود دارد.\n2) مایع مغزی-نخاعی حفره (بطن)های درون آن را پر کرده است.\n3) در یادگیری و تفکر نقش اصلی را دارد.\n4) با لوب بویایی مجاور است.","options":["1","2","3","4"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_44","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('fbb5a32a062b23d5e7b3d25b5a9d84be','persian-konkur-1404-second-biology-1','biology','زیست‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_45","subjectId":"biology","chapter":"زیست‌شناسی — کنکور ۱۴۰۴","prompt":"در یکی از لایه‌های ساختار بافتی دیوارهٔ نای انسان، بخش حجیمی وجود دارد که دو انتهای آن توسط بافت ماهیچه‌ای صاف به یکدیگر متصل شده است. کدام مورد زیر را نمی‌توان دربارهٔ این بخش بیان نمود؟\n1) در مجاورت با تعدادی غدهٔ ترشحی قرار دارد.\n2) حاصل چین خوردگی مخاط به سمت داخل است.\n3) انواعی از یاخته‌ها، رشته‌های کلاژن و مادهٔ زمینه‌ای دارد.\n4) با فاصله از یاخته‌های سنگ‌فرشی چندلایه‌ای قرار گرفته است.","options":["1","2","3","4"],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_45","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
