INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('55a8568a6d7f570c59497149db5948a7','persian-konkur-1404-second-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_83","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"درباره ویژگیهای مولکولهای آمونیاک، کلروفرم، دی‌متیل‌اتر و هگزان، کدام موارد زیر درست است؟\nالف - گشتاور دو قطبی تنها یک مولکول، برابر صفر است.\nب ـ در دمای اتاق، حالت فیزیکی تنها دو ماده، مایع است.\nج - اتمهای جانبی در مولکولهای آمونیاک و کلروفرم، بار جزئی منفی دارند.\nد ـ در یک مولکول، قویترین نیروی جاذبه بین مولکولی، به‌وجود هیدروژن در ساختار آن وابسته است.","options":["«الف» و «ب»","«الف» و «ج»","«ب» و «د»","«ج» و «د»"],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_83","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ef70a180b9c61b32316c877da991266a','persian-konkur-1404-second-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_84","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"اگر در دمای معین، درصد جرمی محلول سیر شده از یک نمک، برابر ۲۰ باشد، در ۲۰۰ گرم آب مقطر، چند گرم از این نمک حل میشود و انحلال پذیری آن در این دما، چند گرم در ۱۰۰ گرم آب است؟","options":["۵۰ و ۲۵","۴۰ و ۲۰","۴۰ و ۲۵","۵۰ و ۲۰"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_84","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('4ecd6bf0deba7e3375efe94ee25ebcfc','persian-konkur-1404-second-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_85","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"مخلوطی از دو ماده A و D در یک لوله آزمایش به شدت هم زده و سپس هم زدن آنها متوقف میشود. A و D از یکدیگر جدا شده و دو لایه مجزا تشکیل میدهند. اگر D در انتهای لوله و A روی آن جای داشته باشد، کدام مورد درست است؟","options":["A میتواند یک محلول و D حلال خالص آن باشد.","A و D میتوانند دو حالت فیزیکی متفاوت داشته باشند.","A و D میتوانند دو محلول آبی با حل شونده‌های متفاوت باشند.","اگر جرم A و D برابر باشد، حجم A به یقین، کمتر از حجم D است."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_85","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('740724f5a01a0320cefb264bf91a416a','persian-konkur-1404-second-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_87","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"فرمول مولکولی یک ترکیب آلی غیرحلقوی، مشابه فرمول مولکولی «هگزن» است. کدام مورد درباره ویژگی ساختاری این ترکیب، به یقین درست است؟\n1) شمار پیوندهای دوگانه در زنجیره کربنی مولکول آن، برابر یک است.\n2) شمار شاخه های فرعی در زنجیره کربنی مولکول آن، برابر صفر است.\n3) شمار پیوندهای یگانۀ کربن – کربن در زنجیره کربنی، نصف شمار اتم‌های هیدروژن در مولکول آن است.\n4) شمار پیوندهای کربن – هیدروژن در زنجیره کربنی، دو برابر شمار پیوندهای یگانۀ کربن – کربن در مولکول آن است.","options":["شمار پیوندهای دوگانه در زنجیره کربنی مولکول آن، برابر یک است.","شمار شاخه‌های فرعی در زنجیره کربنی مولکول آن، برابر صفر است.","شمار پیوندهای یگانۀ کربن – کربن در زنجیره کربنی، نصف شمار اتم‌های هیدروژن در مولکول آن است.","شمار پیوندهای کربن – هیدروژن در زنجیره کربنی، دو برابر شمار پیوندهای یگانۀ کربن – کربن در مولکول آن است."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_87","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('d620c1e22ea281975394a65cc95397ea','persian-konkur-1404-second-chemistry-1','chemistry','شیمی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_91","subjectId":"chemistry","chapter":"شیمی — کنکور ۱۴۰۴","prompt":"نسبت جرم اتم‌های کربن به جرم اتم‌های هیدروژن، در کدام دو گروه از ترکیب‌های آلی، با افزایش شمار اتم‌های کربن ثابت می‌ماند؟\n1) آمین‌ها و آمیدها\n2) سیکلوآلکان‌ها و آمیدها\n3) آلکن‌ها و آمین‌ها\n4) آلکن‌ها و سیکلوآلکان‌ها","options":["آمین‌ها و آمیدها","سیکلوآلکان‌ها و آمیدها","آلکن‌ها و آمین‌ها","آلکن‌ها و سیکلوآلکان‌ها"],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_91","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
