INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('6c6ecc2d542eae0c4e5f75ba3c707e9a','persian-konkur-1404-second-geology-1','geology','زمین‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_144","subjectId":"geology","chapter":"زمین‌شناسی — کنکور ۱۴۰۴","prompt":"کدام عبارت، توصیف مناسب تری از کاربرد «زمین شناسی ساختمانی» است؟\n(۱) با استفاده از اصول زمین شناسی به ساخت سازههای بزرگ صنعتی، شهری، تجاری و... میپردازد.\n(۲) ساختارهای تشکیل دهنده پوسته زمین و نیروهای به وجود آورنده آنها را شناسایی و بررسی میکند.\n(۳) رفتار و ویژگیهای مواد سطحی زمین از نظر مقاومت در برابر فشارها را برای ساخت سازههای مهم بررسی میکند.\n(۴) علم و فن جمع آوری اطلاعات از ساختهای زمین شناسی و عوارض سطح زمین بدون تماس فیزیکی با آنها را انجام میدهد.","options":["با استفاده از اصول زمین شناسی به ساخت سازههای بزرگ صنعتی، شهری، تجاری و... میپردازد.","ساختارهای تشکیل دهنده پوسته زمین و نیروهای به وجود آورنده آنها را شناسایی و بررسی میکند.","رفتار و ویژگیهای مواد سطحی زمین از نظر مقاومت در برابر فشارها را برای ساخت سازههای مهم بررسی میکند.","علم و فن جمع آوری اطلاعات از ساختهای زمین شناسی و عوارض سطح زمین بدون تماس فیزیکی با آنها را انجام میدهد."],"correctIndex":1,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 2 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_144","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
