INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('f687e2c3dbba3bb593eafc121b418207','persian-konkur-1404-second-geology-1','geology','زمین‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_146","subjectId":"geology","chapter":"زمین‌شناسی — کنکور ۱۴۰۴","prompt":"مهندسین اکتشاف منابع نفت و گاز، جستجوی اولیه خود را برای رسیدن به این منابع باید از کدام مناطق شروع کنند؟\n(۱) ساختمانهای زمین شناسی که مناسب تشکیل نفت گیرها هستند.\n(۲) مناطق نزدیک به دریاهای کم عمق که رسوب گذاری شدید دارند.\n(۳) سنگهای آهکی حفره دار تاقدیسی بالای سطح ایستابی آب\n(۴) چین خوردگیهایی که دارای تاقدیس فراوان هستند.","options":["ساختمانهای زمین شناسی که مناسب تشکیل نفت گیرها هستند.","مناطق نزدیک به دریاهای کم عمق که رسوب گذاری شدید دارند.","سنگهای آهکی حفره دار تاقدیسی بالای سطح ایستابی آب","چین خوردگیهایی که دارای تاقدیس فراوان هستند."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_146","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5f578c9b4246401109554b87c7e91b5e','persian-konkur-1404-second-geology-1','geology','زمین‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_147","subjectId":"geology","chapter":"زمین‌شناسی — کنکور ۱۴۰۴","prompt":"شکل زیر، مراحل اولیه برخورد دو ورقه اقیانوسی به هم را نشان میدهد. پدیده زمین شناختی بعدی در این منطقه کدام خواهد بود؟\n(۱) بسته شدن اقیانوس\n(۲) ایجاد پشته اقیانوسی\n(۳) تشکیل جزایر قوسی\n(۴) به وجود آمدن دراز گودال","options":["بسته شدن اقیانوس","ایجاد پشته اقیانوسی","تشکیل جزایر قوسی","به وجود آمدن دراز گودال"],"correctIndex":2,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 3 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/tajrobi_nobat2_147.jpg"],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_147","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e1dcb7bbb342e6ec577714da5bb9a9d1','persian-konkur-1404-second-geology-1','geology','زمین‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_148","subjectId":"geology","chapter":"زمین‌شناسی — کنکور ۱۴۰۴","prompt":"کدام مراحل چگونگی تشکیل شدن یک رگه معدنی را بهتر نشان میدهد؟\n(۱) آب زیرزمینی - تماس با توده های مذاب - رشد بلورهای بزرگ - تشکیل پگماتیت\n(۲) هوازدگی سنگها - جدا شدن کانیهای چگال تر - تجمع در حفره های خالی سنگ بستر\n(۳) ماگمای در حال سرد شدن - عناصر با چگالی بالا - تشکیل بلور - سقوط بلورها به کف ماگما\n(۴) آب داغ - انحلال برخی از عناصر - جابه جایی - سرد شدن داخل شکستگی ها - ته نشین شدن","options":["آب زیرزمینی - تماس با توده های مذاب - رشد بلورهای بزرگ - تشکیل پگماتیت","هوازدگی سنگها - جدا شدن کانیهای چگال تر - تجمع در حفره های خالی سنگ بستر","ماگمای در حال سرد شدن - عناصر با چگالی بالا - تشکیل بلور - سقوط بلورها به کف ماگما","آب داغ - انحلال برخی از عناصر - جابه جایی - سرد شدن داخل شکستگی ها - ته نشین شدن"],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_148","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
