INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('6f3a9c766029b9dd93136df6769e35d4','persian-konkur-1404-second-geology-1','geology','زمین‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_150","subjectId":"geology","chapter":"زمین‌شناسی — کنکور ۱۴۰۴","prompt":"کدام عبارت یا عبارتها، برای عنصر «بریلیم» درست است؟\nالف ـ با فوران آتشفشانها مقداری از اعماق زمین به سطح آورده میشود.\nب ـ سیلیکات آن با درخشش رنگین کمانی به راحتی قابل شناسایی است.\nج ـ فسفات آن با رنگ سبز یکی از گرانترین جواهرات است.","options":["«الف»","«ب»","«الف» و «ب»","«الف» و «ج»"],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_150","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('079bae8785bcc891f46e8ce90810ac4a','persian-konkur-1404-second-geology-1','geology','زمین‌شناسی — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_151","subjectId":"geology","chapter":"زمین‌شناسی — کنکور ۱۴۰۴","prompt":"کدام عبارتها، برای منطقه b در نقشه زیر درست است؟\nالف ـ اغلب گسلهای اصلی، راستالغز و در جهت شرقی – غربی اند.\nب ـ اغلب سنگهای رسوبی شمالی این منطقه دارای توالی رسوبی منظمی هستند.\nج ـ سنگ‌های رسوبی برخی از نواحی آن دارای ذخایر عظیم نفت است.\nد ـ از داخل سنگهای رسوبی قدیمی آن، فیروزه استخراج میشود.","options":["«ج» و «د»","«الف» و «ج»","«ب» و «د»","«الف» و «ب»"],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/tajrobi_nobat2_151.jpg"],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_151","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
