INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('de49bf768e27c971d68e53463e6749ea','persian-konkur-1404-second-physics-1','physics','فیزیک — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_48","subjectId":"physics","chapter":"فیزیک — کنکور ۱۴۰۴","prompt":"یک چشمه صوت ساکن است و شنونده‌ای در حال دور شدن از آن است. کدام مورد در مقایسه با حالتی که این دو نسبت به هم ساکن‌اند، درست است؟","options":["بسامدی که شنونده می‌شنود کاهش می‌یابد و طول موج دریافتی توسط شنونده ثابت می‌ماند.","بسامدی که شنونده می‌شنود افزایش می‌یابد و طول موج دریافتی توسط شنونده ثابت می‌ماند.","بسامدی که شنونده می‌شنود کاهش می‌یابد و طول موج دریافتی توسط شنونده کوتاه تر می‌شود.","بسامدی که شنونده می‌شنود افزایش می‌یابد و طول موج دریافتی توسط شنونده بلندتر می‌شود."],"correctIndex":0,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 1 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":[],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_48","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e92193a64e38e1272f43beeed6a22e2c','persian-konkur-1404-second-physics-1','physics','فیزیک — کنکور ۱۴۰۴','medium','{"key":"tajrobi_nobat2_49","subjectId":"physics","chapter":"فیزیک — کنکور ۱۴۰۴","prompt":"در شکل زیر، صفحه‌های باردار یک خازن تخت را که بین آن‌ها هوا است، به ولت‌سنج وصل می‌کنیم. اگر دی‌الکتریک در بین صفحات قرار دهیم، کدام مورد درست است؟","options":["انرژی ذخیره شده بین صفحه‌های خازن افزایش می‌یابد.","انرژی ذخیره شده بین صفحه‌های خازن ثابت می‌ماند.","بار روی صفحه‌های خازن افزایش می‌یابد.","بار روی صفحه‌های خازن ثابت می‌ماند."],"correctIndex":3,"explanation":"طبق کلید همراه دادهٔ دفترچهٔ کنکور تجربی ۱۴۰۴ (نوبت دوم)، پاسخ صحیح گزینهٔ 4 است. این منبع پاسخ کلیدی ارائه می‌کند؛ توضیح تشریحی تأییدشده‌ای برای این سؤال در دادهٔ منبع وجود ندارد.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/tajrobi_nobat2_49.jpg"],"source":{"name":"کنکور سراسری تجربی ۱۴۰۴، نوبت دوم — دادهٔ فارسی با کلید پاسخ","url":"https://huggingface.co/datasets/PersianML/persian-konkur-1404","license":"MIT","questionId":"tajrobi_nobat2_49","revision":"683e2788cf05a945bb53d5bd1f3ced0e1dc8c4c46013f2fb95673d9c43527305"}}');
