INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('8fa62205e14d8ef5194b8f21cae67ea8','persian-openstax-bachelor-medicine-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"d3c69a4ccac3d038c0d0bdce9f2908d6","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"در سنتز آب‌گیری، چه موادی تشکیل می‌شوند؟","options":["مونومرها","فقط پلیمرها","آب و پلیمرها","هیچ‌کدام"],"correctIndex":2,"explanation":"در واکنش آب‌گیری، با تشکیل پیوند میان مونومرها یک مولکول آب آزاد می‌شود؛ بنابراین محصول، پلیمر به همراه آب است.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66438/index.cnxml#fs-id1313020","license":"CC-BY-4.0","questionId":"m66438#fs-id1313020","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a02f1a4bafbc2ff671df2883738f6921','persian-openstax-bachelor-medicine-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"f6500922b8f66b6ea4335d02797e8d0f","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"در تجزیهٔ پلیمرها به واحدهای سازنده، کدام واکنش انجام می‌شود؟","options":["هیدرولیز","آب‌گیری","تراکمی","پیوند کووالانسی"],"correctIndex":0,"explanation":"هیدرولیز با مصرف آب، پیوند میان واحدهای سازندهٔ پلیمر را می‌شکند. این فرایند در جهت مخالف سنتز آب‌گیری قرار دارد.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66438/index.cnxml#fs-id1342364","license":"CC-BY-4.0","questionId":"m66438#fs-id1342364","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5210f72db3576b857ad6df44760d4802','persian-openstax-bachelor-medicine-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"08eac6c68ea6ed1c0fb954048a1711f9","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"کدام مورد نمونه‌ای از مونوساکارید است؟","options":["فروکتوز","گلوکز","گالاکتوز","همهٔ موارد"],"correctIndex":3,"explanation":"گلوکز، فروکتوز و گالاکتوز هر سه قند ساده یا مونوساکارید هستند؛ پس گزینهٔ همهٔ موارد درست است.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id2310536","license":"CC-BY-4.0","questionId":"m66440#fs-id2310536","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('8a715a3be920fd6bd447a8a584edec23','persian-openstax-bachelor-medicine-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"80904a5dd6893041fe34810ae8ea12d5","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"سلولز و نشاسته نمونهٔ کدام گروه‌اند؟","options":["مونوساکاریدها","دی‌ساکاریدها","لیپیدها","پلی‌ساکاریدها"],"correctIndex":3,"explanation":"سلولز و نشاسته از تعداد زیادی واحد گلوکز ساخته شده‌اند و پلی‌ساکاریدند. نوع پیوند میان واحدها، ساختار و نقش متفاوت آن‌ها را ایجاد می‌کند.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id1352111","license":"CC-BY-4.0","questionId":"m66440#fs-id1352111","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-bachelor-medicine-genetics-1','زیست‌شناسی · تمرین‌های فارسی','bachelor-medicine','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('88b95722218e2c54ddd5123829ddbae9','persian-openstax-bachelor-medicine-genetics-1','genetics','چرخهٔ سلولی','medium','{"key":"d1247f5ceb4ff34842efb428c0942076","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"تعداد کروموزوم‌های یک سلول دیپلوئید نسبت به سلول هاپلوئید چقدر است؟","options":["یک‌چهارم","نصف","دو برابر","چهار برابر"],"correctIndex":2,"explanation":"سلول هاپلوئید یک مجموعهٔ کروموزومی و سلول دیپلوئید دو مجموعهٔ کروموزومی دارد؛ بنابراین تعداد کروموزوم‌های دیپلوئید دو برابر هاپلوئید است.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id1414909","license":"CC-BY-4.0","questionId":"m66477#fs-id1414909","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('561f6ac74f128e30abd390d43d7d0c09','persian-openstax-bachelor-medicine-genetics-1','genetics','چرخهٔ سلولی','medium','{"key":"92478ced29afd6e47c16f8ac18ef0bee","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"نخستین سطح سازمان‌یافتگی DNA در سلول یوکاریوتی با کدام مولکول حفظ می‌شود؟","options":["کوهسین","کندنسین","کروماتین","هیستون"],"correctIndex":3,"explanation":"DNA به دور مجموعه‌ای از پروتئین‌های هیستونی می‌پیچد و نوکلئوزوم می‌سازد. این بسته‌بندی، نخستین سطح اصلی سازمان‌یافتگی کروماتین است.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id2642317","license":"CC-BY-4.0","questionId":"m66477#fs-id2642317","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('b31e9b9a0f5815a1b4ff6a82e14b63ae','persian-openstax-bachelor-medicine-genetics-1','genetics','چرخهٔ سلولی','medium','{"key":"f01ddcf0ebc5cbf2bb61ccfea017a51b","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"نسخه‌های یکسان کروماتین که در ناحیهٔ سانترومر با کوهسین کنار هم نگه داشته می‌شوند، چه نام دارند؟","options":["هیستون‌ها","نوکلئوزوم‌ها","کروماتین","کروماتیدهای خواهری"],"correctIndex":3,"explanation":"پس از همانندسازی DNA، هر کروموزوم از دو کروماتید خواهری تشکیل می‌شود. این دو نسخه با مجموعه‌های پروتئینی از جمله کوهسین کنار هم حفظ می‌شوند.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id2315550","license":"CC-BY-4.0","questionId":"m66477#fs-id2315550","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('863cd5fd90696b15898126b698fb2bec','persian-openstax-bachelor-medicine-genetics-1','genetics','چرخهٔ سلولی','medium','{"key":"e223494423fb5865103af674926f9e10","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"همانندسازی کروموزوم‌ها در کدام مرحلهٔ چرخهٔ سلولی انجام می‌شود؟","options":["مرحلهٔ G1","مرحلهٔ S","پروفاز","پرومتافاز"],"correctIndex":1,"explanation":"DNA در مرحلهٔ S اینترفاز همانندسازی می‌شود. پروفاز و پرومتافاز از مراحل میتوز هستند که پس از کامل‌شدن همانندسازی رخ می‌دهند.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66478/index.cnxml#fs-id1671396","license":"CC-BY-4.0","questionId":"m66478#fs-id1671396","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('986923881b9444ba89e9b82c8bc9a5d7','persian-openstax-bachelor-medicine-genetics-1','genetics','وراثت مندلی','medium','{"key":"83c1a7342cf130b5271e47727a0ba8e5","subjectId":"genetics","chapter":"وراثت مندلی","prompt":"مندل برای انجام دورگ‌گیری، دانه‌های گرده را از کدام بخش گیاه نر برای باروری بخش ماده منتقل می‌کرد؟","options":["بساک","مادگی","کلاله","دانه"],"correctIndex":0,"explanation":"دانه‌های گرده در بساک پرچم تولید می‌شوند. مندل با کنترل انتقال گرده، آمیزش میان گیاهان انتخابی را انجام می‌داد.","difficulty":"medium","topic":{"title":"وراثت مندلی","important":["در آمیزش دو والد خالص با الل‌های متفاوت، F1 یکنواخت و هتروزیگوت است.","نسبت فنوتیپی F2 در آمیزش تک‌صفتی با غالبیت کامل، ۳ به ۱ است."],"microLesson":"مندل با کنترل انتقال گرده و بررسی صفات مشخص نخودفرنگی، الگوهای وراثت را مطالعه کرد. در غالبیت کامل، فنوتیپ فرد هتروزیگوت مشابه فرد هموزیگوت غالب است. در خودگشنی F1 یک آمیزش تک‌صفتی، نسبت ژنوتیپی ۱ به ۲ به ۱ و نسبت فنوتیپی ۳ به ۱ انتظار می‌رود.","branches":[{"title":"طراحی آزمایش","points":["والدهای خالص","کنترل انتقال گرده از بساک"]},{"title":"پیش‌بینی نسل‌ها","points":["F1: هتروزیگوت یکنواخت","F2: نسبت فنوتیپی ۳ به ۱"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66486/index.cnxml#fs-id1438253","license":"CC-BY-4.0","questionId":"m66486#fs-id1438253","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('230425ddb86004c8bad561f1905add28','persian-openstax-bachelor-medicine-genetics-1','genetics','وراثت مندلی','medium','{"key":"e598901d7151a5ffecbe22b35682de42","subjectId":"genetics","chapter":"وراثت مندلی","prompt":"کدام مورد یکی از هفت صفتی بود که مندل در نخودفرنگی بررسی کرد؟","options":["اندازهٔ گل","شکل سطح دانه","شکل برگ","رنگ ساقه"],"correctIndex":1,"explanation":"مندل صفاتی مانند صاف یا چروکیده‌بودن دانه، رنگ دانه و رنگ گل را بررسی کرد. شکل سطح دانه یکی از صفات هفت‌گانهٔ مطالعه‌شده بود.","difficulty":"medium","topic":{"title":"وراثت مندلی","important":["در آمیزش دو والد خالص با الل‌های متفاوت، F1 یکنواخت و هتروزیگوت است.","نسبت فنوتیپی F2 در آمیزش تک‌صفتی با غالبیت کامل، ۳ به ۱ است."],"microLesson":"مندل با کنترل انتقال گرده و بررسی صفات مشخص نخودفرنگی، الگوهای وراثت را مطالعه کرد. در غالبیت کامل، فنوتیپ فرد هتروزیگوت مشابه فرد هموزیگوت غالب است. در خودگشنی F1 یک آمیزش تک‌صفتی، نسبت ژنوتیپی ۱ به ۲ به ۱ و نسبت فنوتیپی ۳ به ۱ انتظار می‌رود.","branches":[{"title":"طراحی آزمایش","points":["والدهای خالص","کنترل انتقال گرده از بساک"]},{"title":"پیش‌بینی نسل‌ها","points":["F1: هتروزیگوت یکنواخت","F2: نسبت فنوتیپی ۳ به ۱"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66486/index.cnxml#fs-id2571565","license":"CC-BY-4.0","questionId":"m66486#fs-id2571565","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('f9f9afd08c174f9ccc1857ba30cb96df','persian-openstax-bachelor-medicine-genetics-1','genetics','وراثت مندلی','medium','{"key":"a102d909697df425e2dbc2a1d954fc4a","subjectId":"genetics","chapter":"وراثت مندلی","prompt":"در نخودفرنگی، رنگ زرد دانه بر سبز غالب است. از آمیزش دو والد خالص با دانه‌های سبز و زرد، چه نسل F1 انتظار می‌رود؟","options":["۱۰۰٪ دانه‌های زردـسبز","۱۰۰٪ دانه‌های زرد","۵۰٪ زرد و ۵۰٪ سبز","۲۵٪ سبز و ۷۵٪ زرد"],"correctIndex":1,"explanation":"در آمیزش والد زرد خالص با والد سبز خالص، همهٔ افراد F1 هتروزیگوت‌اند. چون الل زرد غالب است، همهٔ آن‌ها فنوتیپ زرد نشان می‌دهند.","difficulty":"medium","topic":{"title":"وراثت مندلی","important":["در آمیزش دو والد خالص با الل‌های متفاوت، F1 یکنواخت و هتروزیگوت است.","نسبت فنوتیپی F2 در آمیزش تک‌صفتی با غالبیت کامل، ۳ به ۱ است."],"microLesson":"مندل با کنترل انتقال گرده و بررسی صفات مشخص نخودفرنگی، الگوهای وراثت را مطالعه کرد. در غالبیت کامل، فنوتیپ فرد هتروزیگوت مشابه فرد هموزیگوت غالب است. در خودگشنی F1 یک آمیزش تک‌صفتی، نسبت ژنوتیپی ۱ به ۲ به ۱ و نسبت فنوتیپی ۳ به ۱ انتظار می‌رود.","branches":[{"title":"طراحی آزمایش","points":["والدهای خالص","کنترل انتقال گرده از بساک"]},{"title":"پیش‌بینی نسل‌ها","points":["F1: هتروزیگوت یکنواخت","F2: نسبت فنوتیپی ۳ به ۱"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66486/index.cnxml#fs-id1635350","license":"CC-BY-4.0","questionId":"m66486#fs-id1635350","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a557fb1b1a745ff3a6feedcc7588e43c','persian-openstax-bachelor-medicine-genetics-1','genetics','ساختار و عملکرد DNA','medium','{"key":"089bb74e0ea7b241d4bc716b65efd697","subjectId":"genetics","chapter":"ساختار و عملکرد DNA","prompt":"اگر DNA دو‌رشته‌ای یک گونه دارای ۲۷٪ آدنین باشد، درصد سیتوزین آن چقدر است؟","options":["۲۷٪","۳۰٪","۲۳٪","۵۴٪"],"correctIndex":2,"explanation":"در DNA دو‌رشته‌ای، مقدار A با T و مقدار G با C برابر است. با ۲۷٪ آدنین، مجموع A و T برابر ۵۴٪ می‌شود؛ ۴۶٪ باقی‌مانده به طور مساوی میان G و C تقسیم می‌شود، پس C برابر ۲۳٪ است.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66386/index.cnxml#fs-id2897046","license":"CC-BY-4.0","questionId":"m66386#fs-id2897046","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('f6b7b1757222e8330495b88c4f2cf7d9','persian-openstax-bachelor-medicine-genetics-1','genetics','ساختار و عملکرد DNA','medium','{"key":"5ee6a66549f49f8c4427abdc256c977a","subjectId":"genetics","chapter":"ساختار و عملکرد DNA","prompt":"کدام یافتهٔ آزمایش هرشی و چیس به تأیید نقش DNA به عنوان مادهٔ وراثتی کمک کرد؟","options":["وجود فاژهای رادیواکتیو در رسوب","وجود سلول‌های رادیواکتیو در مایع رویی","وجود گوگرد رادیواکتیو درون سلول","وجود فسفر رادیواکتیو درون سلول"],"correctIndex":3,"explanation":"هرشی و چیس DNA فاژ را با فسفر رادیواکتیو و پروتئین آن را با گوگرد رادیواکتیو نشان‌دار کردند. ورود نشانِ فسفر به سلول‌ها، نقش DNA در انتقال اطلاعات وراثتی را تأیید کرد.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66386/index.cnxml#fs-id1435268","license":"CC-BY-4.0","questionId":"m66386#fs-id1435268","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('c231d8bf6c159ca7a5a9ffbc5df7bda1','persian-openstax-bachelor-medicine-genetics-1','genetics','ساختار و عملکرد DNA','medium','{"key":"795ab2b081ecd9f171b0b936d63bd217","subjectId":"genetics","chapter":"ساختار و عملکرد DNA","prompt":"کدام مورد در مارپیچ دوگانهٔ معمول DNA وجود ندارد؟","options":["آرایش پادموازی","جفت‌شدن مکمل بازها","شیارهای بزرگ و کوچک","اوراسیل"],"correctIndex":3,"explanation":"DNA معمولاً دارای تیمین است و اوراسیل از بازهای رایج RNA است. پادموازی‌بودن رشته‌ها، مکمل‌بودن بازها و شیارهای بزرگ و کوچک از ویژگی‌های DNA دو‌رشته‌ای‌اند.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66387/index.cnxml#fs-id2709296","license":"CC-BY-4.0","questionId":"m66387#fs-id2709296","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a386ae6d44eda3406b65811aef96b54b','persian-openstax-bachelor-medicine-genetics-1','genetics','ساختار و عملکرد DNA','medium','{"key":"7b947295770e38800cd485f4a35942fd","subjectId":"genetics","chapter":"ساختار و عملکرد DNA","prompt":"در یوکاریوت‌ها، DNA به دور کدام ساختار می‌پیچد؟","options":["پروتئین‌های متصل‌شونده به DNA تک‌رشته‌ای","گیرهٔ لغزنده","پلیمراز","هیستون‌ها"],"correctIndex":3,"explanation":"در ساختار نوکلئوزوم، DNA به دور هسته‌ای از پروتئین‌های هیستونی پیچیده است. این سازمان‌یافتگی به فشرده‌سازی و تنظیم دسترسی به DNA کمک می‌کند.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66387/index.cnxml#fs-id2688539","license":"CC-BY-4.0","questionId":"m66387#fs-id2688539","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-bachelor-medicine-histology-1','زیست‌شناسی · تمرین‌های فارسی','bachelor-medicine','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('7345b8e05173383d89f43d7cab0a3c9a','persian-openstax-bachelor-medicine-histology-1','histology','ساختار سلول','medium','{"key":"60200f97a53035e90125402c0a1ec9c0","subjectId":"histology","chapter":"ساختار سلول","prompt":"دانشمندان هنگام مشاهدهٔ نمونه با میکروسکوپ نوری، برای تمایز اجزای سلول از چه چیزی استفاده می‌کنند؟","options":["باریکهٔ الکترونی","ایزوتوپ‌های رادیواکتیو","رنگ‌های ویژه","دمای بالا"],"correctIndex":2,"explanation":"رنگ‌آمیزی، کنتراست اجزای سلول را در میکروسکوپ نوری افزایش می‌دهد. باریکهٔ الکترونی مربوط به میکروسکوپ الکترونی است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1775146","license":"CC-BY-4.0","questionId":"m66445#fs-id1775146","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ef7cd178f2484ca30ed3dd95ba025124','persian-openstax-bachelor-medicine-histology-1','histology','ساختار سلول','medium','{"key":"aafb00a225f4a46a704a1b82c0c244ca","subjectId":"histology","chapter":"ساختار سلول","prompt":"واحد پایهٔ حیات کدام است؟","options":["جاندار","سلول","بافت","اندام"],"correctIndex":1,"explanation":"سلول کوچک‌ترین واحد ساختاری و عملکردی حیات است. بافت‌ها و اندام‌ها از سازمان‌یافتن سلول‌ها پدید می‌آیند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1989359","license":"CC-BY-4.0","questionId":"m66445#fs-id1989359","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('2ace7633839110266ccafa51996e6b10','persian-openstax-bachelor-medicine-histology-1','histology','ساختار سلول','medium','{"key":"49c087763ba066310136acd82320c776","subjectId":"histology","chapter":"ساختار سلول","prompt":"پروکاریوت‌ها برای دریافت برخی مواد و دفع مواد زائد، به کدام فرایند وابسته‌اند؟","options":["ریبوزوم‌ها","تاژک‌ها","تقسیم سلولی","انتشار"],"correctIndex":3,"explanation":"اندازهٔ کوچک پروکاریوت‌ها و نسبت سطح به حجم بالای آن‌ها، تبادل برخی مواد با انتشار را امکان‌پذیر می‌کند. ریبوزوم نقش ساخت پروتئین دارد و تاژک در حرکت دخالت می‌کند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id1617238","license":"CC-BY-4.0","questionId":"m66446#fs-id1617238","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('c920b9b8d56ef71f3dc6d4118402436d','persian-openstax-bachelor-medicine-histology-1','histology','ساختار سلول','medium','{"key":"e9b6214f2f0e17275232c4a80dcafad5","subjectId":"histology","chapter":"ساختار سلول","prompt":"باکتری‌های فاقد فیمبریه، در انجام کدام کار توانایی کمتری دارند؟","options":["چسبیدن به سطح سلول‌ها","شناکردن در مایعات بدن","ساخت پروتئین","حفظ توانایی تقسیم"],"correctIndex":0,"explanation":"فیمبریه‌ها زوائد کوتاه سطح باکتری هستند و در اتصال باکتری به سطوح نقش دارند. حرکت شناوری معمولاً به تاژک مربوط است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id866358","license":"CC-BY-4.0","questionId":"m66446#fs-id866358","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-bachelor-medicine-physiology-1','زیست‌شناسی · تمرین‌های فارسی','bachelor-medicine','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ec4659dc59c417c293d446ad89658802','persian-openstax-bachelor-medicine-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"39dc68cfa0a9fe3b3be3503133698c7e","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"کدام جزء غشای پلاسمایی می‌تواند هم روی سطح غشا و هم درون ساختار آن قرار گیرد؟","options":["پروتئین","کلسترول","کربوهیدرات","فسفولیپید"],"correctIndex":0,"explanation":"پروتئین‌های محیطی روی سطح غشا قرار می‌گیرند، در حالی که پروتئین‌های یکپارچه در دولایهٔ لیپیدی جای دارند یا از آن عبور می‌کنند.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id1511651","license":"CC-BY-4.0","questionId":"m66373#fs-id1511651","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('be839962fc48732be24df393e7907515','persian-openstax-bachelor-medicine-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"43dac3985a6dbbab4c1828ad68a5c03e","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"کدام ویژگی فسفولیپید به سیالیت بیشتر غشا کمک می‌کند؟","options":["سر آن","کلسترول","دم اسید چرب اشباع","پیوندهای دوگانه در دم اسید چرب"],"correctIndex":3,"explanation":"پیوندهای دوگانهٔ سیس در اسیدهای چرب، خمیدگی ایجاد می‌کنند و مانع فشرده‌شدن کامل دم‌ها کنار هم می‌شوند؛ در نتیجه سیالیت غشا افزایش می‌یابد.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id1268735","license":"CC-BY-4.0","questionId":"m66373#fs-id1268735","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('10b944cc1e4e019e152026cab47c4eff','persian-openstax-bachelor-medicine-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"5d12a68db2288c059ba84b93be8c3bf8","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"کارکرد اصلی کربوهیدرات‌های متصل به سطح بیرونی غشای سلول چیست؟","options":["شناسایی سلول","انعطاف‌پذیری غشا","تقویت مکانیکی غشا","ایجاد کانال در غشا"],"correctIndex":0,"explanation":"زنجیره‌های کربوهیدراتی سطح سلول، در شناسایی سلولی و برهم‌کنش میان سلول‌ها نقش دارند. این زنجیره‌ها به پروتئین‌ها یا لیپیدها متصل‌اند.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id2163365","license":"CC-BY-4.0","questionId":"m66373#fs-id2163365","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('429487f5e5beb236af80fcd9542dfc23','persian-openstax-bachelor-medicine-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"1907c7dbe84b0c7d055e0ca866dfdbf4","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"آب در فرایند اسمز در کدام جهت حرکت می‌کند؟","options":["در سراسر سیتوپلاسم بدون وابستگی به غلظت","از ناحیهٔ با غلظت بیشتر سایر مواد حل‌شده به غلظت کمتر آن‌ها","از ناحیهٔ با غلظت بیشتر آب به ناحیهٔ با غلظت کمتر آب","از ناحیهٔ با غلظت کمتر آب به ناحیهٔ با غلظت بیشتر آب"],"correctIndex":2,"explanation":"اسمز، حرکت خالص آب از میان غشای دارای نفوذپذیری انتخابی است. در صورت نبود اختلاف فشار مؤثر، آب از ناحیهٔ با غلظت بیشتر آب به ناحیهٔ با غلظت کمتر آب می‌رود.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-id1422483","license":"CC-BY-4.0","questionId":"m66374#fs-id1422483","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ac91b4de2ff12a05a50348155e6c2a0f','persian-openstax-bachelor-medicine-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"22e39a9ab2ef56a72b9c3963ce5e75d7","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"در نخودفرنگی، غلاف پُر بر غلاف فشرده غالب است. اگر در نسل F2 یک آمیزش تک‌صفتی ۶۵۰ گیاه با غلاف پُر به دست آید، حدوداً چند گیاه با غلاف فشرده انتظار می‌رود؟","options":["۶۰۰","۱۶۵","۲۱۷","۴۶۸"],"correctIndex":2,"explanation":"نسبت فنوتیپی مورد انتظار در F2 این آمیزش ۳ غالب به ۱ مغلوب است. پس تعداد غلاف فشرده تقریباً ۶۵۰ تقسیم بر ۳، یعنی ۲۱۷ است.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-id1243838","license":"CC-BY-4.0","questionId":"m66374#fs-id1243838","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-dental-basics-biochemistry-1','زیست‌شناسی · تمرین‌های فارسی','dental-basics','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('cfe1ccb24aba81ef154abac0db946b80','persian-openstax-dental-basics-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"d3c69a4ccac3d038c0d0bdce9f2908d6","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"در سنتز آب‌گیری، چه موادی تشکیل می‌شوند؟","options":["مونومرها","فقط پلیمرها","آب و پلیمرها","هیچ‌کدام"],"correctIndex":2,"explanation":"در واکنش آب‌گیری، با تشکیل پیوند میان مونومرها یک مولکول آب آزاد می‌شود؛ بنابراین محصول، پلیمر به همراه آب است.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66438/index.cnxml#fs-id1313020","license":"CC-BY-4.0","questionId":"m66438#fs-id1313020","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('1f4ae508602523e060b4a779c2f5dae9','persian-openstax-dental-basics-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"f6500922b8f66b6ea4335d02797e8d0f","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"در تجزیهٔ پلیمرها به واحدهای سازنده، کدام واکنش انجام می‌شود؟","options":["هیدرولیز","آب‌گیری","تراکمی","پیوند کووالانسی"],"correctIndex":0,"explanation":"هیدرولیز با مصرف آب، پیوند میان واحدهای سازندهٔ پلیمر را می‌شکند. این فرایند در جهت مخالف سنتز آب‌گیری قرار دارد.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66438/index.cnxml#fs-id1342364","license":"CC-BY-4.0","questionId":"m66438#fs-id1342364","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e25aaff63dc47c7f6c1dc9b03df53dfb','persian-openstax-dental-basics-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"08eac6c68ea6ed1c0fb954048a1711f9","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"کدام مورد نمونه‌ای از مونوساکارید است؟","options":["فروکتوز","گلوکز","گالاکتوز","همهٔ موارد"],"correctIndex":3,"explanation":"گلوکز، فروکتوز و گالاکتوز هر سه قند ساده یا مونوساکارید هستند؛ پس گزینهٔ همهٔ موارد درست است.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id2310536","license":"CC-BY-4.0","questionId":"m66440#fs-id2310536","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('f4cc70fb5524ddca7ea7732590fa243f','persian-openstax-dental-basics-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"80904a5dd6893041fe34810ae8ea12d5","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"سلولز و نشاسته نمونهٔ کدام گروه‌اند؟","options":["مونوساکاریدها","دی‌ساکاریدها","لیپیدها","پلی‌ساکاریدها"],"correctIndex":3,"explanation":"سلولز و نشاسته از تعداد زیادی واحد گلوکز ساخته شده‌اند و پلی‌ساکاریدند. نوع پیوند میان واحدها، ساختار و نقش متفاوت آن‌ها را ایجاد می‌کند.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id1352111","license":"CC-BY-4.0","questionId":"m66440#fs-id1352111","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-dental-basics-histology-1','زیست‌شناسی · تمرین‌های فارسی','dental-basics','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('fbfd3f99049a28fbb12534aeab77be4f','persian-openstax-dental-basics-histology-1','histology','ساختار سلول','medium','{"key":"60200f97a53035e90125402c0a1ec9c0","subjectId":"histology","chapter":"ساختار سلول","prompt":"دانشمندان هنگام مشاهدهٔ نمونه با میکروسکوپ نوری، برای تمایز اجزای سلول از چه چیزی استفاده می‌کنند؟","options":["باریکهٔ الکترونی","ایزوتوپ‌های رادیواکتیو","رنگ‌های ویژه","دمای بالا"],"correctIndex":2,"explanation":"رنگ‌آمیزی، کنتراست اجزای سلول را در میکروسکوپ نوری افزایش می‌دهد. باریکهٔ الکترونی مربوط به میکروسکوپ الکترونی است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1775146","license":"CC-BY-4.0","questionId":"m66445#fs-id1775146","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5a097e3ac2e484b823bd647a5c9ec0a2','persian-openstax-dental-basics-histology-1','histology','ساختار سلول','medium','{"key":"aafb00a225f4a46a704a1b82c0c244ca","subjectId":"histology","chapter":"ساختار سلول","prompt":"واحد پایهٔ حیات کدام است؟","options":["جاندار","سلول","بافت","اندام"],"correctIndex":1,"explanation":"سلول کوچک‌ترین واحد ساختاری و عملکردی حیات است. بافت‌ها و اندام‌ها از سازمان‌یافتن سلول‌ها پدید می‌آیند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1989359","license":"CC-BY-4.0","questionId":"m66445#fs-id1989359","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('32703a0b5378f5a3e84ee4fada179ec6','persian-openstax-dental-basics-histology-1','histology','ساختار سلول','medium','{"key":"49c087763ba066310136acd82320c776","subjectId":"histology","chapter":"ساختار سلول","prompt":"پروکاریوت‌ها برای دریافت برخی مواد و دفع مواد زائد، به کدام فرایند وابسته‌اند؟","options":["ریبوزوم‌ها","تاژک‌ها","تقسیم سلولی","انتشار"],"correctIndex":3,"explanation":"اندازهٔ کوچک پروکاریوت‌ها و نسبت سطح به حجم بالای آن‌ها، تبادل برخی مواد با انتشار را امکان‌پذیر می‌کند. ریبوزوم نقش ساخت پروتئین دارد و تاژک در حرکت دخالت می‌کند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id1617238","license":"CC-BY-4.0","questionId":"m66446#fs-id1617238","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('2d8d0c8af012a7c9a5c3d7dde040c6b0','persian-openstax-dental-basics-histology-1','histology','ساختار سلول','medium','{"key":"e9b6214f2f0e17275232c4a80dcafad5","subjectId":"histology","chapter":"ساختار سلول","prompt":"باکتری‌های فاقد فیمبریه، در انجام کدام کار توانایی کمتری دارند؟","options":["چسبیدن به سطح سلول‌ها","شناکردن در مایعات بدن","ساخت پروتئین","حفظ توانایی تقسیم"],"correctIndex":0,"explanation":"فیمبریه‌ها زوائد کوتاه سطح باکتری هستند و در اتصال باکتری به سطوح نقش دارند. حرکت شناوری معمولاً به تاژک مربوط است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id866358","license":"CC-BY-4.0","questionId":"m66446#fs-id866358","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-konkur-biology-1','زیست‌شناسی · تمرین‌های فارسی','konkur','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('76b4b153ee129ac40cf31d66c16c1e2a','persian-openstax-konkur-biology-1','biology','مولکول‌های زیستی','medium','{"key":"d3c69a4ccac3d038c0d0bdce9f2908d6","subjectId":"biology","chapter":"مولکول‌های زیستی","prompt":"در سنتز آب‌گیری، چه موادی تشکیل می‌شوند؟","options":["مونومرها","فقط پلیمرها","آب و پلیمرها","هیچ‌کدام"],"correctIndex":2,"explanation":"در واکنش آب‌گیری، با تشکیل پیوند میان مونومرها یک مولکول آب آزاد می‌شود؛ بنابراین محصول، پلیمر به همراه آب است.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66438/index.cnxml#fs-id1313020","license":"CC-BY-4.0","questionId":"m66438#fs-id1313020","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('2c8835deb063708888e36d6133305c34','persian-openstax-konkur-biology-1','biology','مولکول‌های زیستی','medium','{"key":"f6500922b8f66b6ea4335d02797e8d0f","subjectId":"biology","chapter":"مولکول‌های زیستی","prompt":"در تجزیهٔ پلیمرها به واحدهای سازنده، کدام واکنش انجام می‌شود؟","options":["هیدرولیز","آب‌گیری","تراکمی","پیوند کووالانسی"],"correctIndex":0,"explanation":"هیدرولیز با مصرف آب، پیوند میان واحدهای سازندهٔ پلیمر را می‌شکند. این فرایند در جهت مخالف سنتز آب‌گیری قرار دارد.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66438/index.cnxml#fs-id1342364","license":"CC-BY-4.0","questionId":"m66438#fs-id1342364","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('37c1de3c099598355c10d4225be21276','persian-openstax-konkur-biology-1','biology','مولکول‌های زیستی','medium','{"key":"08eac6c68ea6ed1c0fb954048a1711f9","subjectId":"biology","chapter":"مولکول‌های زیستی","prompt":"کدام مورد نمونه‌ای از مونوساکارید است؟","options":["فروکتوز","گلوکز","گالاکتوز","همهٔ موارد"],"correctIndex":3,"explanation":"گلوکز، فروکتوز و گالاکتوز هر سه قند ساده یا مونوساکارید هستند؛ پس گزینهٔ همهٔ موارد درست است.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id2310536","license":"CC-BY-4.0","questionId":"m66440#fs-id2310536","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('404cc19bd786c94a3841fb322a05162a','persian-openstax-konkur-biology-1','biology','مولکول‌های زیستی','medium','{"key":"80904a5dd6893041fe34810ae8ea12d5","subjectId":"biology","chapter":"مولکول‌های زیستی","prompt":"سلولز و نشاسته نمونهٔ کدام گروه‌اند؟","options":["مونوساکاریدها","دی‌ساکاریدها","لیپیدها","پلی‌ساکاریدها"],"correctIndex":3,"explanation":"سلولز و نشاسته از تعداد زیادی واحد گلوکز ساخته شده‌اند و پلی‌ساکاریدند. نوع پیوند میان واحدها، ساختار و نقش متفاوت آن‌ها را ایجاد می‌کند.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id1352111","license":"CC-BY-4.0","questionId":"m66440#fs-id1352111","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a1531f7d169029d5e9b6f39f0b79f063','persian-openstax-konkur-biology-1','biology','ساختار سلول','medium','{"key":"60200f97a53035e90125402c0a1ec9c0","subjectId":"biology","chapter":"ساختار سلول","prompt":"دانشمندان هنگام مشاهدهٔ نمونه با میکروسکوپ نوری، برای تمایز اجزای سلول از چه چیزی استفاده می‌کنند؟","options":["باریکهٔ الکترونی","ایزوتوپ‌های رادیواکتیو","رنگ‌های ویژه","دمای بالا"],"correctIndex":2,"explanation":"رنگ‌آمیزی، کنتراست اجزای سلول را در میکروسکوپ نوری افزایش می‌دهد. باریکهٔ الکترونی مربوط به میکروسکوپ الکترونی است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1775146","license":"CC-BY-4.0","questionId":"m66445#fs-id1775146","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('363c6c61fa02c163ac8b9dc035b91c82','persian-openstax-konkur-biology-1','biology','ساختار سلول','medium','{"key":"aafb00a225f4a46a704a1b82c0c244ca","subjectId":"biology","chapter":"ساختار سلول","prompt":"واحد پایهٔ حیات کدام است؟","options":["جاندار","سلول","بافت","اندام"],"correctIndex":1,"explanation":"سلول کوچک‌ترین واحد ساختاری و عملکردی حیات است. بافت‌ها و اندام‌ها از سازمان‌یافتن سلول‌ها پدید می‌آیند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1989359","license":"CC-BY-4.0","questionId":"m66445#fs-id1989359","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('62b85440891adec3bb5ddd6867d341fe','persian-openstax-konkur-biology-1','biology','ساختار سلول','medium','{"key":"49c087763ba066310136acd82320c776","subjectId":"biology","chapter":"ساختار سلول","prompt":"پروکاریوت‌ها برای دریافت برخی مواد و دفع مواد زائد، به کدام فرایند وابسته‌اند؟","options":["ریبوزوم‌ها","تاژک‌ها","تقسیم سلولی","انتشار"],"correctIndex":3,"explanation":"اندازهٔ کوچک پروکاریوت‌ها و نسبت سطح به حجم بالای آن‌ها، تبادل برخی مواد با انتشار را امکان‌پذیر می‌کند. ریبوزوم نقش ساخت پروتئین دارد و تاژک در حرکت دخالت می‌کند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id1617238","license":"CC-BY-4.0","questionId":"m66446#fs-id1617238","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('c89572465c27730a3bdc456e5019b2fe','persian-openstax-konkur-biology-1','biology','ساختار سلول','medium','{"key":"e9b6214f2f0e17275232c4a80dcafad5","subjectId":"biology","chapter":"ساختار سلول","prompt":"باکتری‌های فاقد فیمبریه، در انجام کدام کار توانایی کمتری دارند؟","options":["چسبیدن به سطح سلول‌ها","شناکردن در مایعات بدن","ساخت پروتئین","حفظ توانایی تقسیم"],"correctIndex":0,"explanation":"فیمبریه‌ها زوائد کوتاه سطح باکتری هستند و در اتصال باکتری به سطوح نقش دارند. حرکت شناوری معمولاً به تاژک مربوط است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id866358","license":"CC-BY-4.0","questionId":"m66446#fs-id866358","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('de18bccbe6ed5a8330c6eb2c0471b9d7','persian-openstax-konkur-biology-1','biology','غشا و جابه‌جایی مواد','medium','{"key":"39dc68cfa0a9fe3b3be3503133698c7e","subjectId":"biology","chapter":"غشا و جابه‌جایی مواد","prompt":"کدام جزء غشای پلاسمایی می‌تواند هم روی سطح غشا و هم درون ساختار آن قرار گیرد؟","options":["پروتئین","کلسترول","کربوهیدرات","فسفولیپید"],"correctIndex":0,"explanation":"پروتئین‌های محیطی روی سطح غشا قرار می‌گیرند، در حالی که پروتئین‌های یکپارچه در دولایهٔ لیپیدی جای دارند یا از آن عبور می‌کنند.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id1511651","license":"CC-BY-4.0","questionId":"m66373#fs-id1511651","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('bd92f3a181f187fc1b4f44542e566e56','persian-openstax-konkur-biology-1','biology','غشا و جابه‌جایی مواد','medium','{"key":"43dac3985a6dbbab4c1828ad68a5c03e","subjectId":"biology","chapter":"غشا و جابه‌جایی مواد","prompt":"کدام ویژگی فسفولیپید به سیالیت بیشتر غشا کمک می‌کند؟","options":["سر آن","کلسترول","دم اسید چرب اشباع","پیوندهای دوگانه در دم اسید چرب"],"correctIndex":3,"explanation":"پیوندهای دوگانهٔ سیس در اسیدهای چرب، خمیدگی ایجاد می‌کنند و مانع فشرده‌شدن کامل دم‌ها کنار هم می‌شوند؛ در نتیجه سیالیت غشا افزایش می‌یابد.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id1268735","license":"CC-BY-4.0","questionId":"m66373#fs-id1268735","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5aae07d402a54b71b8abbf544776adb3','persian-openstax-konkur-biology-1','biology','غشا و جابه‌جایی مواد','medium','{"key":"5d12a68db2288c059ba84b93be8c3bf8","subjectId":"biology","chapter":"غشا و جابه‌جایی مواد","prompt":"کارکرد اصلی کربوهیدرات‌های متصل به سطح بیرونی غشای سلول چیست؟","options":["شناسایی سلول","انعطاف‌پذیری غشا","تقویت مکانیکی غشا","ایجاد کانال در غشا"],"correctIndex":0,"explanation":"زنجیره‌های کربوهیدراتی سطح سلول، در شناسایی سلولی و برهم‌کنش میان سلول‌ها نقش دارند. این زنجیره‌ها به پروتئین‌ها یا لیپیدها متصل‌اند.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id2163365","license":"CC-BY-4.0","questionId":"m66373#fs-id2163365","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('30ca5e3027093bd9d3746519d7662998','persian-openstax-konkur-biology-1','biology','غشا و جابه‌جایی مواد','medium','{"key":"1907c7dbe84b0c7d055e0ca866dfdbf4","subjectId":"biology","chapter":"غشا و جابه‌جایی مواد","prompt":"آب در فرایند اسمز در کدام جهت حرکت می‌کند؟","options":["در سراسر سیتوپلاسم بدون وابستگی به غلظت","از ناحیهٔ با غلظت بیشتر سایر مواد حل‌شده به غلظت کمتر آن‌ها","از ناحیهٔ با غلظت بیشتر آب به ناحیهٔ با غلظت کمتر آب","از ناحیهٔ با غلظت کمتر آب به ناحیهٔ با غلظت بیشتر آب"],"correctIndex":2,"explanation":"اسمز، حرکت خالص آب از میان غشای دارای نفوذپذیری انتخابی است. در صورت نبود اختلاف فشار مؤثر، آب از ناحیهٔ با غلظت بیشتر آب به ناحیهٔ با غلظت کمتر آب می‌رود.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-id1422483","license":"CC-BY-4.0","questionId":"m66374#fs-id1422483","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('02cbeb3b165b8c9e7667c616bc9c9474','persian-openstax-konkur-biology-1','biology','چرخهٔ سلولی','medium','{"key":"d1247f5ceb4ff34842efb428c0942076","subjectId":"biology","chapter":"چرخهٔ سلولی","prompt":"تعداد کروموزوم‌های یک سلول دیپلوئید نسبت به سلول هاپلوئید چقدر است؟","options":["یک‌چهارم","نصف","دو برابر","چهار برابر"],"correctIndex":2,"explanation":"سلول هاپلوئید یک مجموعهٔ کروموزومی و سلول دیپلوئید دو مجموعهٔ کروموزومی دارد؛ بنابراین تعداد کروموزوم‌های دیپلوئید دو برابر هاپلوئید است.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id1414909","license":"CC-BY-4.0","questionId":"m66477#fs-id1414909","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('de3b943ef9587a918fdfe58061a50ff0','persian-openstax-konkur-biology-1','biology','چرخهٔ سلولی','medium','{"key":"92478ced29afd6e47c16f8ac18ef0bee","subjectId":"biology","chapter":"چرخهٔ سلولی","prompt":"نخستین سطح سازمان‌یافتگی DNA در سلول یوکاریوتی با کدام مولکول حفظ می‌شود؟","options":["کوهسین","کندنسین","کروماتین","هیستون"],"correctIndex":3,"explanation":"DNA به دور مجموعه‌ای از پروتئین‌های هیستونی می‌پیچد و نوکلئوزوم می‌سازد. این بسته‌بندی، نخستین سطح اصلی سازمان‌یافتگی کروماتین است.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id2642317","license":"CC-BY-4.0","questionId":"m66477#fs-id2642317","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('8b5b831253ca6d00766b6f5f985be185','persian-openstax-konkur-biology-1','biology','چرخهٔ سلولی','medium','{"key":"f01ddcf0ebc5cbf2bb61ccfea017a51b","subjectId":"biology","chapter":"چرخهٔ سلولی","prompt":"نسخه‌های یکسان کروماتین که در ناحیهٔ سانترومر با کوهسین کنار هم نگه داشته می‌شوند، چه نام دارند؟","options":["هیستون‌ها","نوکلئوزوم‌ها","کروماتین","کروماتیدهای خواهری"],"correctIndex":3,"explanation":"پس از همانندسازی DNA، هر کروموزوم از دو کروماتید خواهری تشکیل می‌شود. این دو نسخه با مجموعه‌های پروتئینی از جمله کوهسین کنار هم حفظ می‌شوند.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id2315550","license":"CC-BY-4.0","questionId":"m66477#fs-id2315550","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('613cfd26a797073900948bc1a9bc6a00','persian-openstax-konkur-biology-1','biology','چرخهٔ سلولی','medium','{"key":"e223494423fb5865103af674926f9e10","subjectId":"biology","chapter":"چرخهٔ سلولی","prompt":"همانندسازی کروموزوم‌ها در کدام مرحلهٔ چرخهٔ سلولی انجام می‌شود؟","options":["مرحلهٔ G1","مرحلهٔ S","پروفاز","پرومتافاز"],"correctIndex":1,"explanation":"DNA در مرحلهٔ S اینترفاز همانندسازی می‌شود. پروفاز و پرومتافاز از مراحل میتوز هستند که پس از کامل‌شدن همانندسازی رخ می‌دهند.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66478/index.cnxml#fs-id1671396","license":"CC-BY-4.0","questionId":"m66478#fs-id1671396","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('e9b20708e7cdc4eb3f75748dcc7dbd2e','persian-openstax-konkur-biology-1','biology','وراثت مندلی','medium','{"key":"83c1a7342cf130b5271e47727a0ba8e5","subjectId":"biology","chapter":"وراثت مندلی","prompt":"مندل برای انجام دورگ‌گیری، دانه‌های گرده را از کدام بخش گیاه نر برای باروری بخش ماده منتقل می‌کرد؟","options":["بساک","مادگی","کلاله","دانه"],"correctIndex":0,"explanation":"دانه‌های گرده در بساک پرچم تولید می‌شوند. مندل با کنترل انتقال گرده، آمیزش میان گیاهان انتخابی را انجام می‌داد.","difficulty":"medium","topic":{"title":"وراثت مندلی","important":["در آمیزش دو والد خالص با الل‌های متفاوت، F1 یکنواخت و هتروزیگوت است.","نسبت فنوتیپی F2 در آمیزش تک‌صفتی با غالبیت کامل، ۳ به ۱ است."],"microLesson":"مندل با کنترل انتقال گرده و بررسی صفات مشخص نخودفرنگی، الگوهای وراثت را مطالعه کرد. در غالبیت کامل، فنوتیپ فرد هتروزیگوت مشابه فرد هموزیگوت غالب است. در خودگشنی F1 یک آمیزش تک‌صفتی، نسبت ژنوتیپی ۱ به ۲ به ۱ و نسبت فنوتیپی ۳ به ۱ انتظار می‌رود.","branches":[{"title":"طراحی آزمایش","points":["والدهای خالص","کنترل انتقال گرده از بساک"]},{"title":"پیش‌بینی نسل‌ها","points":["F1: هتروزیگوت یکنواخت","F2: نسبت فنوتیپی ۳ به ۱"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66486/index.cnxml#fs-id1438253","license":"CC-BY-4.0","questionId":"m66486#fs-id1438253","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('6858fa9d57ccaeb8b450f1038703fbb5','persian-openstax-konkur-biology-1','biology','وراثت مندلی','medium','{"key":"e598901d7151a5ffecbe22b35682de42","subjectId":"biology","chapter":"وراثت مندلی","prompt":"کدام مورد یکی از هفت صفتی بود که مندل در نخودفرنگی بررسی کرد؟","options":["اندازهٔ گل","شکل سطح دانه","شکل برگ","رنگ ساقه"],"correctIndex":1,"explanation":"مندل صفاتی مانند صاف یا چروکیده‌بودن دانه، رنگ دانه و رنگ گل را بررسی کرد. شکل سطح دانه یکی از صفات هفت‌گانهٔ مطالعه‌شده بود.","difficulty":"medium","topic":{"title":"وراثت مندلی","important":["در آمیزش دو والد خالص با الل‌های متفاوت، F1 یکنواخت و هتروزیگوت است.","نسبت فنوتیپی F2 در آمیزش تک‌صفتی با غالبیت کامل، ۳ به ۱ است."],"microLesson":"مندل با کنترل انتقال گرده و بررسی صفات مشخص نخودفرنگی، الگوهای وراثت را مطالعه کرد. در غالبیت کامل، فنوتیپ فرد هتروزیگوت مشابه فرد هموزیگوت غالب است. در خودگشنی F1 یک آمیزش تک‌صفتی، نسبت ژنوتیپی ۱ به ۲ به ۱ و نسبت فنوتیپی ۳ به ۱ انتظار می‌رود.","branches":[{"title":"طراحی آزمایش","points":["والدهای خالص","کنترل انتقال گرده از بساک"]},{"title":"پیش‌بینی نسل‌ها","points":["F1: هتروزیگوت یکنواخت","F2: نسبت فنوتیپی ۳ به ۱"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66486/index.cnxml#fs-id2571565","license":"CC-BY-4.0","questionId":"m66486#fs-id2571565","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('154dfb822ae96729c26bd7712c4425c2','persian-openstax-konkur-biology-1','biology','وراثت مندلی','medium','{"key":"a102d909697df425e2dbc2a1d954fc4a","subjectId":"biology","chapter":"وراثت مندلی","prompt":"در نخودفرنگی، رنگ زرد دانه بر سبز غالب است. از آمیزش دو والد خالص با دانه‌های سبز و زرد، چه نسل F1 انتظار می‌رود؟","options":["۱۰۰٪ دانه‌های زردـسبز","۱۰۰٪ دانه‌های زرد","۵۰٪ زرد و ۵۰٪ سبز","۲۵٪ سبز و ۷۵٪ زرد"],"correctIndex":1,"explanation":"در آمیزش والد زرد خالص با والد سبز خالص، همهٔ افراد F1 هتروزیگوت‌اند. چون الل زرد غالب است، همهٔ آن‌ها فنوتیپ زرد نشان می‌دهند.","difficulty":"medium","topic":{"title":"وراثت مندلی","important":["در آمیزش دو والد خالص با الل‌های متفاوت، F1 یکنواخت و هتروزیگوت است.","نسبت فنوتیپی F2 در آمیزش تک‌صفتی با غالبیت کامل، ۳ به ۱ است."],"microLesson":"مندل با کنترل انتقال گرده و بررسی صفات مشخص نخودفرنگی، الگوهای وراثت را مطالعه کرد. در غالبیت کامل، فنوتیپ فرد هتروزیگوت مشابه فرد هموزیگوت غالب است. در خودگشنی F1 یک آمیزش تک‌صفتی، نسبت ژنوتیپی ۱ به ۲ به ۱ و نسبت فنوتیپی ۳ به ۱ انتظار می‌رود.","branches":[{"title":"طراحی آزمایش","points":["والدهای خالص","کنترل انتقال گرده از بساک"]},{"title":"پیش‌بینی نسل‌ها","points":["F1: هتروزیگوت یکنواخت","F2: نسبت فنوتیپی ۳ به ۱"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66486/index.cnxml#fs-id1635350","license":"CC-BY-4.0","questionId":"m66486#fs-id1635350","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('f7203a157bb472f5b6b04931f4225e9c','persian-openstax-konkur-biology-1','biology','غشا و جابه‌جایی مواد','medium','{"key":"22e39a9ab2ef56a72b9c3963ce5e75d7","subjectId":"biology","chapter":"غشا و جابه‌جایی مواد","prompt":"در نخودفرنگی، غلاف پُر بر غلاف فشرده غالب است. اگر در نسل F2 یک آمیزش تک‌صفتی ۶۵۰ گیاه با غلاف پُر به دست آید، حدوداً چند گیاه با غلاف فشرده انتظار می‌رود؟","options":["۶۰۰","۱۶۵","۲۱۷","۴۶۸"],"correctIndex":2,"explanation":"نسبت فنوتیپی مورد انتظار در F2 این آمیزش ۳ غالب به ۱ مغلوب است. پس تعداد غلاف فشرده تقریباً ۶۵۰ تقسیم بر ۳، یعنی ۲۱۷ است.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-id1243838","license":"CC-BY-4.0","questionId":"m66374#fs-id1243838","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ff9ec4708ffb4eb3db323ff09bed0920','persian-openstax-konkur-biology-1','biology','ساختار و عملکرد DNA','medium','{"key":"089bb74e0ea7b241d4bc716b65efd697","subjectId":"biology","chapter":"ساختار و عملکرد DNA","prompt":"اگر DNA دو‌رشته‌ای یک گونه دارای ۲۷٪ آدنین باشد، درصد سیتوزین آن چقدر است؟","options":["۲۷٪","۳۰٪","۲۳٪","۵۴٪"],"correctIndex":2,"explanation":"در DNA دو‌رشته‌ای، مقدار A با T و مقدار G با C برابر است. با ۲۷٪ آدنین، مجموع A و T برابر ۵۴٪ می‌شود؛ ۴۶٪ باقی‌مانده به طور مساوی میان G و C تقسیم می‌شود، پس C برابر ۲۳٪ است.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66386/index.cnxml#fs-id2897046","license":"CC-BY-4.0","questionId":"m66386#fs-id2897046","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('25813dfc84312fc29c2f4fe6fe661fda','persian-openstax-konkur-biology-1','biology','ساختار و عملکرد DNA','medium','{"key":"5ee6a66549f49f8c4427abdc256c977a","subjectId":"biology","chapter":"ساختار و عملکرد DNA","prompt":"کدام یافتهٔ آزمایش هرشی و چیس به تأیید نقش DNA به عنوان مادهٔ وراثتی کمک کرد؟","options":["وجود فاژهای رادیواکتیو در رسوب","وجود سلول‌های رادیواکتیو در مایع رویی","وجود گوگرد رادیواکتیو درون سلول","وجود فسفر رادیواکتیو درون سلول"],"correctIndex":3,"explanation":"هرشی و چیس DNA فاژ را با فسفر رادیواکتیو و پروتئین آن را با گوگرد رادیواکتیو نشان‌دار کردند. ورود نشانِ فسفر به سلول‌ها، نقش DNA در انتقال اطلاعات وراثتی را تأیید کرد.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66386/index.cnxml#fs-id1435268","license":"CC-BY-4.0","questionId":"m66386#fs-id1435268","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('dd77daa89be48fb177dc284561f2e517','persian-openstax-konkur-biology-1','biology','ساختار و عملکرد DNA','medium','{"key":"795ab2b081ecd9f171b0b936d63bd217","subjectId":"biology","chapter":"ساختار و عملکرد DNA","prompt":"کدام مورد در مارپیچ دوگانهٔ معمول DNA وجود ندارد؟","options":["آرایش پادموازی","جفت‌شدن مکمل بازها","شیارهای بزرگ و کوچک","اوراسیل"],"correctIndex":3,"explanation":"DNA معمولاً دارای تیمین است و اوراسیل از بازهای رایج RNA است. پادموازی‌بودن رشته‌ها، مکمل‌بودن بازها و شیارهای بزرگ و کوچک از ویژگی‌های DNA دو‌رشته‌ای‌اند.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66387/index.cnxml#fs-id2709296","license":"CC-BY-4.0","questionId":"m66387#fs-id2709296","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('f50bc5983d171afc130df45da3ee0f56','persian-openstax-konkur-biology-1','biology','ساختار و عملکرد DNA','medium','{"key":"7b947295770e38800cd485f4a35942fd","subjectId":"biology","chapter":"ساختار و عملکرد DNA","prompt":"در یوکاریوت‌ها، DNA به دور کدام ساختار می‌پیچد؟","options":["پروتئین‌های متصل‌شونده به DNA تک‌رشته‌ای","گیرهٔ لغزنده","پلیمراز","هیستون‌ها"],"correctIndex":3,"explanation":"در ساختار نوکلئوزوم، DNA به دور هسته‌ای از پروتئین‌های هیستونی پیچیده است. این سازمان‌یافتگی به فشرده‌سازی و تنظیم دسترسی به DNA کمک می‌کند.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66387/index.cnxml#fs-id2688539","license":"CC-BY-4.0","questionId":"m66387#fs-id2688539","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-medical-basics-biochemistry-1','زیست‌شناسی · تمرین‌های فارسی','medical-basics','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('37d739c17e9e5d871ebb68563077f289','persian-openstax-medical-basics-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"d3c69a4ccac3d038c0d0bdce9f2908d6","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"در سنتز آب‌گیری، چه موادی تشکیل می‌شوند؟","options":["مونومرها","فقط پلیمرها","آب و پلیمرها","هیچ‌کدام"],"correctIndex":2,"explanation":"در واکنش آب‌گیری، با تشکیل پیوند میان مونومرها یک مولکول آب آزاد می‌شود؛ بنابراین محصول، پلیمر به همراه آب است.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66438/index.cnxml#fs-id1313020","license":"CC-BY-4.0","questionId":"m66438#fs-id1313020","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('ae20c9af1ebdc7c977da97aea5b14b64','persian-openstax-medical-basics-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"f6500922b8f66b6ea4335d02797e8d0f","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"در تجزیهٔ پلیمرها به واحدهای سازنده، کدام واکنش انجام می‌شود؟","options":["هیدرولیز","آب‌گیری","تراکمی","پیوند کووالانسی"],"correctIndex":0,"explanation":"هیدرولیز با مصرف آب، پیوند میان واحدهای سازندهٔ پلیمر را می‌شکند. این فرایند در جهت مخالف سنتز آب‌گیری قرار دارد.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66438/index.cnxml#fs-id1342364","license":"CC-BY-4.0","questionId":"m66438#fs-id1342364","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('35dbe81851c82b27d2c52246ca944c83','persian-openstax-medical-basics-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"08eac6c68ea6ed1c0fb954048a1711f9","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"کدام مورد نمونه‌ای از مونوساکارید است؟","options":["فروکتوز","گلوکز","گالاکتوز","همهٔ موارد"],"correctIndex":3,"explanation":"گلوکز، فروکتوز و گالاکتوز هر سه قند ساده یا مونوساکارید هستند؛ پس گزینهٔ همهٔ موارد درست است.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id2310536","license":"CC-BY-4.0","questionId":"m66440#fs-id2310536","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('465b1fc47dd6904ee688b6a5f19f6102','persian-openstax-medical-basics-biochemistry-1','biochemistry','مولکول‌های زیستی','medium','{"key":"80904a5dd6893041fe34810ae8ea12d5","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"سلولز و نشاسته نمونهٔ کدام گروه‌اند؟","options":["مونوساکاریدها","دی‌ساکاریدها","لیپیدها","پلی‌ساکاریدها"],"correctIndex":3,"explanation":"سلولز و نشاسته از تعداد زیادی واحد گلوکز ساخته شده‌اند و پلی‌ساکاریدند. نوع پیوند میان واحدها، ساختار و نقش متفاوت آن‌ها را ایجاد می‌کند.","difficulty":"medium","topic":{"title":"مولکول‌های زیستی","important":["آب‌گیری با آزادشدن آب، پیوند می‌سازد؛ هیدرولیز با مصرف آب پیوند را می‌شکند.","گلوکز، فروکتوز و گالاکتوز مونوساکارید هستند."],"microLesson":"مونومرها واحدهای سازندهٔ مولکول‌های بزرگ‌اند. در بسیاری از واکنش‌های تشکیل پلیمر، مولکول آب آزاد می‌شود. در هیدرولیز، آب برای شکستن پیوند به کار می‌رود. نشاسته و سلولز هر دو پلیمر گلوکز هستند، اما به علت تفاوت پیوندها، ساختار و نقش متفاوتی دارند.","branches":[{"title":"ساخت و تجزیه","points":["آب‌گیری: تشکیل پیوند و آزادشدن آب","هیدرولیز: شکستن پیوند با مصرف آب"]},{"title":"کربوهیدرات‌ها","points":["مونوساکارید: گلوکز و فروکتوز","پلی‌ساکارید: نشاسته و سلولز"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id1352111","license":"CC-BY-4.0","questionId":"m66440#fs-id1352111","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-medical-basics-genetics-1','زیست‌شناسی · تمرین‌های فارسی','medical-basics','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('7b99de27383ac0ee483d68c69de6014d','persian-openstax-medical-basics-genetics-1','genetics','چرخهٔ سلولی','medium','{"key":"d1247f5ceb4ff34842efb428c0942076","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"تعداد کروموزوم‌های یک سلول دیپلوئید نسبت به سلول هاپلوئید چقدر است؟","options":["یک‌چهارم","نصف","دو برابر","چهار برابر"],"correctIndex":2,"explanation":"سلول هاپلوئید یک مجموعهٔ کروموزومی و سلول دیپلوئید دو مجموعهٔ کروموزومی دارد؛ بنابراین تعداد کروموزوم‌های دیپلوئید دو برابر هاپلوئید است.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id1414909","license":"CC-BY-4.0","questionId":"m66477#fs-id1414909","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('3c91f18634d45937fdfe2464831400a4','persian-openstax-medical-basics-genetics-1','genetics','چرخهٔ سلولی','medium','{"key":"92478ced29afd6e47c16f8ac18ef0bee","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"نخستین سطح سازمان‌یافتگی DNA در سلول یوکاریوتی با کدام مولکول حفظ می‌شود؟","options":["کوهسین","کندنسین","کروماتین","هیستون"],"correctIndex":3,"explanation":"DNA به دور مجموعه‌ای از پروتئین‌های هیستونی می‌پیچد و نوکلئوزوم می‌سازد. این بسته‌بندی، نخستین سطح اصلی سازمان‌یافتگی کروماتین است.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id2642317","license":"CC-BY-4.0","questionId":"m66477#fs-id2642317","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('c51e2fcd644f5c9d169a9ed18372fa8a','persian-openstax-medical-basics-genetics-1','genetics','چرخهٔ سلولی','medium','{"key":"f01ddcf0ebc5cbf2bb61ccfea017a51b","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"نسخه‌های یکسان کروماتین که در ناحیهٔ سانترومر با کوهسین کنار هم نگه داشته می‌شوند، چه نام دارند؟","options":["هیستون‌ها","نوکلئوزوم‌ها","کروماتین","کروماتیدهای خواهری"],"correctIndex":3,"explanation":"پس از همانندسازی DNA، هر کروموزوم از دو کروماتید خواهری تشکیل می‌شود. این دو نسخه با مجموعه‌های پروتئینی از جمله کوهسین کنار هم حفظ می‌شوند.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id2315550","license":"CC-BY-4.0","questionId":"m66477#fs-id2315550","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('a9da44c56ccf186cbd4c67d936cec995','persian-openstax-medical-basics-genetics-1','genetics','چرخهٔ سلولی','medium','{"key":"e223494423fb5865103af674926f9e10","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"همانندسازی کروموزوم‌ها در کدام مرحلهٔ چرخهٔ سلولی انجام می‌شود؟","options":["مرحلهٔ G1","مرحلهٔ S","پروفاز","پرومتافاز"],"correctIndex":1,"explanation":"DNA در مرحلهٔ S اینترفاز همانندسازی می‌شود. پروفاز و پرومتافاز از مراحل میتوز هستند که پس از کامل‌شدن همانندسازی رخ می‌دهند.","difficulty":"medium","topic":{"title":"چرخهٔ سلولی و کروموزوم","important":["همانندسازی DNA در مرحلهٔ S انجام می‌شود.","کروماتیدهای خواهری نسخه‌های حاصل از همانندسازی‌اند."],"microLesson":"سلول دیپلوئید دو مجموعه و سلول هاپلوئید یک مجموعهٔ کروموزومی دارد. DNA یوکاریوتی با پیچیدن به دور هیستون‌ها نوکلئوزوم می‌سازد. در مرحلهٔ S، همانندسازی DNA دو کروماتید خواهری ایجاد می‌کند. سپس این نسخه‌ها در تقسیم سلولی از هم جدا می‌شوند.","branches":[{"title":"سازمان‌یافتگی","points":["DNA و هیستون","نوکلئوزوم و کروماتین"]},{"title":"چرخهٔ سلولی","points":["مرحلهٔ S: همانندسازی","کروماتیدهای خواهری و کوهسین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66478/index.cnxml#fs-id1671396","license":"CC-BY-4.0","questionId":"m66478#fs-id1671396","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('fb84d0381d0fc6b2927d4ff1ed2a349b','persian-openstax-medical-basics-genetics-1','genetics','وراثت مندلی','medium','{"key":"83c1a7342cf130b5271e47727a0ba8e5","subjectId":"genetics","chapter":"وراثت مندلی","prompt":"مندل برای انجام دورگ‌گیری، دانه‌های گرده را از کدام بخش گیاه نر برای باروری بخش ماده منتقل می‌کرد؟","options":["بساک","مادگی","کلاله","دانه"],"correctIndex":0,"explanation":"دانه‌های گرده در بساک پرچم تولید می‌شوند. مندل با کنترل انتقال گرده، آمیزش میان گیاهان انتخابی را انجام می‌داد.","difficulty":"medium","topic":{"title":"وراثت مندلی","important":["در آمیزش دو والد خالص با الل‌های متفاوت، F1 یکنواخت و هتروزیگوت است.","نسبت فنوتیپی F2 در آمیزش تک‌صفتی با غالبیت کامل، ۳ به ۱ است."],"microLesson":"مندل با کنترل انتقال گرده و بررسی صفات مشخص نخودفرنگی، الگوهای وراثت را مطالعه کرد. در غالبیت کامل، فنوتیپ فرد هتروزیگوت مشابه فرد هموزیگوت غالب است. در خودگشنی F1 یک آمیزش تک‌صفتی، نسبت ژنوتیپی ۱ به ۲ به ۱ و نسبت فنوتیپی ۳ به ۱ انتظار می‌رود.","branches":[{"title":"طراحی آزمایش","points":["والدهای خالص","کنترل انتقال گرده از بساک"]},{"title":"پیش‌بینی نسل‌ها","points":["F1: هتروزیگوت یکنواخت","F2: نسبت فنوتیپی ۳ به ۱"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66486/index.cnxml#fs-id1438253","license":"CC-BY-4.0","questionId":"m66486#fs-id1438253","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('c1e42de7b3e95e21fcc893d05771bb0f','persian-openstax-medical-basics-genetics-1','genetics','وراثت مندلی','medium','{"key":"e598901d7151a5ffecbe22b35682de42","subjectId":"genetics","chapter":"وراثت مندلی","prompt":"کدام مورد یکی از هفت صفتی بود که مندل در نخودفرنگی بررسی کرد؟","options":["اندازهٔ گل","شکل سطح دانه","شکل برگ","رنگ ساقه"],"correctIndex":1,"explanation":"مندل صفاتی مانند صاف یا چروکیده‌بودن دانه، رنگ دانه و رنگ گل را بررسی کرد. شکل سطح دانه یکی از صفات هفت‌گانهٔ مطالعه‌شده بود.","difficulty":"medium","topic":{"title":"وراثت مندلی","important":["در آمیزش دو والد خالص با الل‌های متفاوت، F1 یکنواخت و هتروزیگوت است.","نسبت فنوتیپی F2 در آمیزش تک‌صفتی با غالبیت کامل، ۳ به ۱ است."],"microLesson":"مندل با کنترل انتقال گرده و بررسی صفات مشخص نخودفرنگی، الگوهای وراثت را مطالعه کرد. در غالبیت کامل، فنوتیپ فرد هتروزیگوت مشابه فرد هموزیگوت غالب است. در خودگشنی F1 یک آمیزش تک‌صفتی، نسبت ژنوتیپی ۱ به ۲ به ۱ و نسبت فنوتیپی ۳ به ۱ انتظار می‌رود.","branches":[{"title":"طراحی آزمایش","points":["والدهای خالص","کنترل انتقال گرده از بساک"]},{"title":"پیش‌بینی نسل‌ها","points":["F1: هتروزیگوت یکنواخت","F2: نسبت فنوتیپی ۳ به ۱"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66486/index.cnxml#fs-id2571565","license":"CC-BY-4.0","questionId":"m66486#fs-id2571565","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('0b7cde10b56fcd9e731bc4636751cc5f','persian-openstax-medical-basics-genetics-1','genetics','وراثت مندلی','medium','{"key":"a102d909697df425e2dbc2a1d954fc4a","subjectId":"genetics","chapter":"وراثت مندلی","prompt":"در نخودفرنگی، رنگ زرد دانه بر سبز غالب است. از آمیزش دو والد خالص با دانه‌های سبز و زرد، چه نسل F1 انتظار می‌رود؟","options":["۱۰۰٪ دانه‌های زردـسبز","۱۰۰٪ دانه‌های زرد","۵۰٪ زرد و ۵۰٪ سبز","۲۵٪ سبز و ۷۵٪ زرد"],"correctIndex":1,"explanation":"در آمیزش والد زرد خالص با والد سبز خالص، همهٔ افراد F1 هتروزیگوت‌اند. چون الل زرد غالب است، همهٔ آن‌ها فنوتیپ زرد نشان می‌دهند.","difficulty":"medium","topic":{"title":"وراثت مندلی","important":["در آمیزش دو والد خالص با الل‌های متفاوت، F1 یکنواخت و هتروزیگوت است.","نسبت فنوتیپی F2 در آمیزش تک‌صفتی با غالبیت کامل، ۳ به ۱ است."],"microLesson":"مندل با کنترل انتقال گرده و بررسی صفات مشخص نخودفرنگی، الگوهای وراثت را مطالعه کرد. در غالبیت کامل، فنوتیپ فرد هتروزیگوت مشابه فرد هموزیگوت غالب است. در خودگشنی F1 یک آمیزش تک‌صفتی، نسبت ژنوتیپی ۱ به ۲ به ۱ و نسبت فنوتیپی ۳ به ۱ انتظار می‌رود.","branches":[{"title":"طراحی آزمایش","points":["والدهای خالص","کنترل انتقال گرده از بساک"]},{"title":"پیش‌بینی نسل‌ها","points":["F1: هتروزیگوت یکنواخت","F2: نسبت فنوتیپی ۳ به ۱"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66486/index.cnxml#fs-id1635350","license":"CC-BY-4.0","questionId":"m66486#fs-id1635350","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('915e83acfedd0c9cbc6003f73c44cf92','persian-openstax-medical-basics-genetics-1','genetics','ساختار و عملکرد DNA','medium','{"key":"089bb74e0ea7b241d4bc716b65efd697","subjectId":"genetics","chapter":"ساختار و عملکرد DNA","prompt":"اگر DNA دو‌رشته‌ای یک گونه دارای ۲۷٪ آدنین باشد، درصد سیتوزین آن چقدر است؟","options":["۲۷٪","۳۰٪","۲۳٪","۵۴٪"],"correctIndex":2,"explanation":"در DNA دو‌رشته‌ای، مقدار A با T و مقدار G با C برابر است. با ۲۷٪ آدنین، مجموع A و T برابر ۵۴٪ می‌شود؛ ۴۶٪ باقی‌مانده به طور مساوی میان G و C تقسیم می‌شود، پس C برابر ۲۳٪ است.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66386/index.cnxml#fs-id2897046","license":"CC-BY-4.0","questionId":"m66386#fs-id2897046","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('3e2aeed8b391aeb5e6e9a596b8f90cdc','persian-openstax-medical-basics-genetics-1','genetics','ساختار و عملکرد DNA','medium','{"key":"5ee6a66549f49f8c4427abdc256c977a","subjectId":"genetics","chapter":"ساختار و عملکرد DNA","prompt":"کدام یافتهٔ آزمایش هرشی و چیس به تأیید نقش DNA به عنوان مادهٔ وراثتی کمک کرد؟","options":["وجود فاژهای رادیواکتیو در رسوب","وجود سلول‌های رادیواکتیو در مایع رویی","وجود گوگرد رادیواکتیو درون سلول","وجود فسفر رادیواکتیو درون سلول"],"correctIndex":3,"explanation":"هرشی و چیس DNA فاژ را با فسفر رادیواکتیو و پروتئین آن را با گوگرد رادیواکتیو نشان‌دار کردند. ورود نشانِ فسفر به سلول‌ها، نقش DNA در انتقال اطلاعات وراثتی را تأیید کرد.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66386/index.cnxml#fs-id1435268","license":"CC-BY-4.0","questionId":"m66386#fs-id1435268","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('f52345adcb2c11364cb153b7b4e71c6f','persian-openstax-medical-basics-genetics-1','genetics','ساختار و عملکرد DNA','medium','{"key":"795ab2b081ecd9f171b0b936d63bd217","subjectId":"genetics","chapter":"ساختار و عملکرد DNA","prompt":"کدام مورد در مارپیچ دوگانهٔ معمول DNA وجود ندارد؟","options":["آرایش پادموازی","جفت‌شدن مکمل بازها","شیارهای بزرگ و کوچک","اوراسیل"],"correctIndex":3,"explanation":"DNA معمولاً دارای تیمین است و اوراسیل از بازهای رایج RNA است. پادموازی‌بودن رشته‌ها، مکمل‌بودن بازها و شیارهای بزرگ و کوچک از ویژگی‌های DNA دو‌رشته‌ای‌اند.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66387/index.cnxml#fs-id2709296","license":"CC-BY-4.0","questionId":"m66387#fs-id2709296","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('5e53a3074a926d9b10031c2cb7f9a892','persian-openstax-medical-basics-genetics-1','genetics','ساختار و عملکرد DNA','medium','{"key":"7b947295770e38800cd485f4a35942fd","subjectId":"genetics","chapter":"ساختار و عملکرد DNA","prompt":"در یوکاریوت‌ها، DNA به دور کدام ساختار می‌پیچد؟","options":["پروتئین‌های متصل‌شونده به DNA تک‌رشته‌ای","گیرهٔ لغزنده","پلیمراز","هیستون‌ها"],"correctIndex":3,"explanation":"در ساختار نوکلئوزوم، DNA به دور هسته‌ای از پروتئین‌های هیستونی پیچیده است. این سازمان‌یافتگی به فشرده‌سازی و تنظیم دسترسی به DNA کمک می‌کند.","difficulty":"medium","topic":{"title":"ساختار DNA و مادهٔ وراثتی","important":["در DNA دو‌رشته‌ای A برابر T و G برابر C است.","فسفر رادیواکتیو در آزمایش هرشی و چیس، نشانگر DNA بود."],"microLesson":"دو رشتهٔ DNA آرایش پادموازی دارند و بازهای آن‌ها به‌صورت مکمل جفت می‌شوند. آدنین با تیمین و گوانین با سیتوزین جفت می‌شود. آزمایش هرشی و چیس با نشاندارکردن جداگانهٔ DNA و پروتئین فاژ، شواهدی برای نقش وراثتی DNA فراهم کرد. در یوکاریوت‌ها DNA به دور هیستون‌ها می‌پیچد.","branches":[{"title":"ساختار","points":["رشته‌های پادموازی و بازهای مکمل","هیستون و نوکلئوزوم"]},{"title":"شواهد وراثتی","points":["فسفر برای نشان‌گذاری DNA","گوگرد برای نشان‌گذاری پروتئین"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66387/index.cnxml#fs-id2688539","license":"CC-BY-4.0","questionId":"m66387#fs-id2688539","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-medical-basics-histology-1','زیست‌شناسی · تمرین‌های فارسی','medical-basics','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('9f89c01ddfafb170c5f37b9167013bc5','persian-openstax-medical-basics-histology-1','histology','ساختار سلول','medium','{"key":"60200f97a53035e90125402c0a1ec9c0","subjectId":"histology","chapter":"ساختار سلول","prompt":"دانشمندان هنگام مشاهدهٔ نمونه با میکروسکوپ نوری، برای تمایز اجزای سلول از چه چیزی استفاده می‌کنند؟","options":["باریکهٔ الکترونی","ایزوتوپ‌های رادیواکتیو","رنگ‌های ویژه","دمای بالا"],"correctIndex":2,"explanation":"رنگ‌آمیزی، کنتراست اجزای سلول را در میکروسکوپ نوری افزایش می‌دهد. باریکهٔ الکترونی مربوط به میکروسکوپ الکترونی است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1775146","license":"CC-BY-4.0","questionId":"m66445#fs-id1775146","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('679da82a894b80537812424fc7eb0b21','persian-openstax-medical-basics-histology-1','histology','ساختار سلول','medium','{"key":"aafb00a225f4a46a704a1b82c0c244ca","subjectId":"histology","chapter":"ساختار سلول","prompt":"واحد پایهٔ حیات کدام است؟","options":["جاندار","سلول","بافت","اندام"],"correctIndex":1,"explanation":"سلول کوچک‌ترین واحد ساختاری و عملکردی حیات است. بافت‌ها و اندام‌ها از سازمان‌یافتن سلول‌ها پدید می‌آیند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1989359","license":"CC-BY-4.0","questionId":"m66445#fs-id1989359","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('6b620b2cc73910edb017d957e8dcfc97','persian-openstax-medical-basics-histology-1','histology','ساختار سلول','medium','{"key":"49c087763ba066310136acd82320c776","subjectId":"histology","chapter":"ساختار سلول","prompt":"پروکاریوت‌ها برای دریافت برخی مواد و دفع مواد زائد، به کدام فرایند وابسته‌اند؟","options":["ریبوزوم‌ها","تاژک‌ها","تقسیم سلولی","انتشار"],"correctIndex":3,"explanation":"اندازهٔ کوچک پروکاریوت‌ها و نسبت سطح به حجم بالای آن‌ها، تبادل برخی مواد با انتشار را امکان‌پذیر می‌کند. ریبوزوم نقش ساخت پروتئین دارد و تاژک در حرکت دخالت می‌کند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id1617238","license":"CC-BY-4.0","questionId":"m66446#fs-id1617238","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('dd0025f90686960080e07e41c8edd845','persian-openstax-medical-basics-histology-1','histology','ساختار سلول','medium','{"key":"e9b6214f2f0e17275232c4a80dcafad5","subjectId":"histology","chapter":"ساختار سلول","prompt":"باکتری‌های فاقد فیمبریه، در انجام کدام کار توانایی کمتری دارند؟","options":["چسبیدن به سطح سلول‌ها","شناکردن در مایعات بدن","ساخت پروتئین","حفظ توانایی تقسیم"],"correctIndex":0,"explanation":"فیمبریه‌ها زوائد کوتاه سطح باکتری هستند و در اتصال باکتری به سطوح نقش دارند. حرکت شناوری معمولاً به تاژک مربوط است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id866358","license":"CC-BY-4.0","questionId":"m66446#fs-id866358","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-openstax-medical-basics-physiology-1','زیست‌شناسی · تمرین‌های فارسی','medical-basics','reference','openstax',NULL,'تمرین فارسی',1793577600000,0,'زیست‌شناسی ۲ — کلارک، داگلاس و چوی / اوپن‌استکس. ترجمه و توضیح فارسی: سوئیت استادی. نسخهٔ ۲۰ دسامبر ۲۰۲۴، CC BY 4.0. تمرین کتاب درسی؛ سؤال رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('4c58c75da7373411b3b6d4e3d05ef228','persian-openstax-medical-basics-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"39dc68cfa0a9fe3b3be3503133698c7e","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"کدام جزء غشای پلاسمایی می‌تواند هم روی سطح غشا و هم درون ساختار آن قرار گیرد؟","options":["پروتئین","کلسترول","کربوهیدرات","فسفولیپید"],"correctIndex":0,"explanation":"پروتئین‌های محیطی روی سطح غشا قرار می‌گیرند، در حالی که پروتئین‌های یکپارچه در دولایهٔ لیپیدی جای دارند یا از آن عبور می‌کنند.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id1511651","license":"CC-BY-4.0","questionId":"m66373#fs-id1511651","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('0d883443ed1c8836ee3568846964b728','persian-openstax-medical-basics-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"43dac3985a6dbbab4c1828ad68a5c03e","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"کدام ویژگی فسفولیپید به سیالیت بیشتر غشا کمک می‌کند؟","options":["سر آن","کلسترول","دم اسید چرب اشباع","پیوندهای دوگانه در دم اسید چرب"],"correctIndex":3,"explanation":"پیوندهای دوگانهٔ سیس در اسیدهای چرب، خمیدگی ایجاد می‌کنند و مانع فشرده‌شدن کامل دم‌ها کنار هم می‌شوند؛ در نتیجه سیالیت غشا افزایش می‌یابد.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id1268735","license":"CC-BY-4.0","questionId":"m66373#fs-id1268735","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('98e45aedb3ee5884ffb02127cb4f449d','persian-openstax-medical-basics-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"5d12a68db2288c059ba84b93be8c3bf8","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"کارکرد اصلی کربوهیدرات‌های متصل به سطح بیرونی غشای سلول چیست؟","options":["شناسایی سلول","انعطاف‌پذیری غشا","تقویت مکانیکی غشا","ایجاد کانال در غشا"],"correctIndex":0,"explanation":"زنجیره‌های کربوهیدراتی سطح سلول، در شناسایی سلولی و برهم‌کنش میان سلول‌ها نقش دارند. این زنجیره‌ها به پروتئین‌ها یا لیپیدها متصل‌اند.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id2163365","license":"CC-BY-4.0","questionId":"m66373#fs-id2163365","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('c1ec4d09632f3ac0ec78e1fde6aaf70e','persian-openstax-medical-basics-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"1907c7dbe84b0c7d055e0ca866dfdbf4","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"آب در فرایند اسمز در کدام جهت حرکت می‌کند؟","options":["در سراسر سیتوپلاسم بدون وابستگی به غلظت","از ناحیهٔ با غلظت بیشتر سایر مواد حل‌شده به غلظت کمتر آن‌ها","از ناحیهٔ با غلظت بیشتر آب به ناحیهٔ با غلظت کمتر آب","از ناحیهٔ با غلظت کمتر آب به ناحیهٔ با غلظت بیشتر آب"],"correctIndex":2,"explanation":"اسمز، حرکت خالص آب از میان غشای دارای نفوذپذیری انتخابی است. در صورت نبود اختلاف فشار مؤثر، آب از ناحیهٔ با غلظت بیشتر آب به ناحیهٔ با غلظت کمتر آب می‌رود.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-id1422483","license":"CC-BY-4.0","questionId":"m66374#fs-id1422483","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('783615e68e08e2d7d1add043c75f3ca0','persian-openstax-medical-basics-physiology-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"22e39a9ab2ef56a72b9c3963ce5e75d7","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"در نخودفرنگی، غلاف پُر بر غلاف فشرده غالب است. اگر در نسل F2 یک آمیزش تک‌صفتی ۶۵۰ گیاه با غلاف پُر به دست آید، حدوداً چند گیاه با غلاف فشرده انتظار می‌رود؟","options":["۶۰۰","۱۶۵","۲۱۷","۴۶۸"],"correctIndex":2,"explanation":"نسبت فنوتیپی مورد انتظار در F2 این آمیزش ۳ غالب به ۱ مغلوب است. پس تعداد غلاف فشرده تقریباً ۶۵۰ تقسیم بر ۳، یعنی ۲۱۷ است.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","images":[],"source":{"name":"زیست‌شناسی ۲ اوپن‌استکس — ترجمه و توضیح فارسی سوئیت استادی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-id1243838","license":"CC-BY-4.0","questionId":"m66374#fs-id1243838","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('persian-preinternship-1402-esfand-clinical-comprehensive-1','پیش‌کارورزی ۱۴۰۲ · اسفند · جامع بالینی','preinternship','national','national',1402,'اسفند',1793577600000,0,'آزمون جامع پیش‌کارورزی اسفند ۱۴۰۲ — مرکز سنجش آموزش پزشکی؛ آرشیو سایت کنکور. حقوق منبع آزمون محفوظ. کلید منبع حفظ شده؛ توضیح تشریحی و درجهٔ سختی تأییدشده در منبع موجود نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES ('6c12658302e859b1ca302ceb9b3ff052','persian-preinternship-1402-esfand-clinical-comprehensive-1','clinical-comprehensive','جامع بالینی','medium','{"key":"preinternship-1402-1","subjectId":"clinical-comprehensive","chapter":"جامع بالینی","prompt":"سؤال 1 آزمون پیش‌کارورزی اسفند ۱۴۰۲؛ متن و گزینه‌های اصلی در تصویر آمده‌اند.","options":["گزینهٔ الف","گزینهٔ ب","گزینهٔ ج","گزینهٔ د"],"correctIndex":1,"explanation":"طبق کلید منتشرشدهٔ آزمون پیش‌کارورزی اسفند ۱۴۰۲، پاسخ صحیح گزینهٔ ب است. سؤال‌های حذف‌شده و چندپاسخیِ اعلام‌شده در اصلاحیهٔ نهایی وارد این مجموعه نشده‌اند. این منبع پاسخ کلیدی دارد و توضیح تشریحی تأییدشده‌ای برای این سؤال منتشر نکرده است.","difficulty":"medium","topic":null,"language":"fa","images":["/question-media/preinternship-1402-1.jpg"],"source":{"name":"آزمون جامع پیش‌کارورزی اسفند ۱۴۰۲ — مرکز سنجش آموزش پزشکی؛ آرشیو سایت کنکور","url":"https://konkur.in/108745","license":"حقوق منبع آزمون محفوظ","questionId":"۱۴۰۲-اسفند-1","revision":"37ba75f1264c2c9aabe2e7b4826ffc1f17c30b45f777b43b3a4f7c9764d9057d"}}');
